function applyPercentageDataBar(
  worksheet: Worksheet,
  cellAddress: string,
  accentColor: string,
  priority: number,
): void {
  const rule = {
    axisPosition: 'none',
    border: false,
    cfvo: [
      { type: 'num', value: 0 },
      { type: 'num', value: 1 },
    ],
    color: { argb: accentColor },
    direction: 'leftToRight',
    gradient: false,
    maxLength: 100,
    minLength: 0,
    priority,
    showValue: true,
    type: 'dataBar',
  };

  worksheet.addConditionalFormatting({
    ref: cellAddress,
    rules: [
      rule as unknown as Parameters<
        Worksheet['addConditionalFormatting']
      >[0]['rules'][0],
    ],
  });
}

