/**
 * Computes the derived summary values used by formulas and cards.
 * @param labels Localized export labels.

code_excerpt:
function buildSummaryComputedValues(
  labels: NpsExcelExportLabels,
  summaryStatistics: SummaryStatistics,
): SummaryComputedValues {
  const detractorsSummary = summaryStatistics.categoryMix[0];
  const passivesSummary = summaryStatistics.categoryMix[1];
  const promotersSummary = summaryStatistics.categoryMix[2];
  let weightedScoreTotal = 0;

  for (const item of summaryStatistics.distribution) {
    weightedScoreTotal += item.score * item.count;
  }

  const averageScore =
    summaryStatistics.totalResponses === 0
      ? 0
      : weightedScoreTotal / summaryStatistics.totalResponses;
  const npsScore = Math.round(
    (promotersSummary.share - detractorsSummary.share) * 100,
  );
  const statusStyle = resolveSummaryStatusStyle(npsScore);

  return {
    averageScore,
    detractorsSummary,
    npsScore,
    passivesSummary,
    promotersSummary,
    statusDescription: resolveStatusDescriptionText(labels, statusStyle.key),
    statusIcon: resolveStatusIconText(statusStyle.key),
    statusIconFont: resolveStatusIconFont(),
    statusStyle,
    statusTitle: resolveStatusTitleText(labels, statusStyle.key),
  };
}

