/**
 * Resolves a part path relative to a workbook XML source path.
 * @param sourcePath Source workbook path.

code_excerpt:
function resolveRelativePartPath(
  sourcePath: string,
  targetPath: string,
): string {
  if (targetPath.startsWith('/')) {
    return targetPath.slice(1);
  }

  const resolvedSegments = sourcePath.split('/');

  resolvedSegments.pop();

  for (const segment of targetPath.split('/')) {
    if (segment === '..') {
      resolvedSegments.pop();
    } else if (segment !== '.' && segment.length > 0) {
      resolvedSegments.push(segment);
    }
  }

  return resolvedSegments.join('/');
}

