/**
 * Resolves the next numeric part index for generated workbook artifacts.
 * @param fileNames Existing file names in the package.

code_excerpt:
function findNextPartIndex(
  fileNames: Array<string>,
  prefix: string,
  suffix: string,
): number {
  const escapedPrefix = escapeRegExp(prefix);
  const escapedSuffix = escapeRegExp(suffix);
  const pattern = new RegExp(
    String.raw`^${escapedPrefix}(\d+)${escapedSuffix}$`,
    'u',
  );

  let highestValue = 0;

  for (const fileName of fileNames) {
    const matchedGroups = pattern.exec(fileName);

    if (matchedGroups) {
      const nextValue = Number.parseInt(matchedGroups[1], 10);

      if (!Number.isNaN(nextValue)) {
        highestValue = Math.max(highestValue, nextValue);
      }
    }
  }

  return highestValue + 1;
}

