/**
 * Ensures a worksheet XML payload references the generated drawing part.
 * @param worksheetXml Worksheet XML payload.

code_excerpt:
function ensureWorksheetDrawingXml(
  worksheetXml: string,
  drawingRelationshipId: string,
): string {
  const drawingNode = `<drawing r:id="${drawingRelationshipId}"/>`;

  if (worksheetXml.includes('<drawing ')) {
    return worksheetXml.replace(
      /<drawing\b[^>]*\br:id="[^"]*"\s*\/>/u,
      drawingNode,
    );
  }

  if (/<extLst\b/u.test(worksheetXml)) {
    return callReplaceAll(worksheetXml, /<extLst\b/gu, `${drawingNode}<extLst`);
  }

  if (worksheetXml.includes('<legacyDrawing ')) {
    return callReplaceAll(
      worksheetXml,
      /<legacyDrawing\b/gu,
      `${drawingNode}<legacyDrawing`,
    );
  }

  return worksheetXml.replace('</worksheet>', `${drawingNode}</worksheet>`);
}

