async function loadScreenConfiguration(force = false): Promise<void> {
  if (!screenId.value) {
    form.value = createEmptyConfiguration();
    return;
  }

  const requestId = activeLoadRequest + 1;
  activeLoadRequest = requestId;
  roleMenuOpen.value = false;
  npsStore.setSelectedScreen(screenId.value);

  // Always map roles correctly on load
  if (screen.value && !force) {
    const config = cloneConfiguration(screen.value.configuration);
    config.allowedRoleIds = Array.isArray(config.allowedRoleIds)
      ? config.allowedRoleIds.map(Number).filter((id) => Number.isFinite(id))
      : [];
    form.value = config;
  }

  // Force reload roles/assignments if entering from app list card
  const nextScreen = await npsStore.loadSelectedScreen(screenId.value, true);

  if (requestId !== activeLoadRequest) {
    return;
  }

  if (nextScreen) {
    const config = cloneConfiguration(nextScreen.configuration);
    config.allowedRoleIds = Array.isArray(config.allowedRoleIds)
      ? config.allowedRoleIds.map(Number).filter((id) => Number.isFinite(id))
      : [];
    form.value = config;
  }
}

