function showAddSideSectionButton(row: SectionRow): boolean {
  // Defensive: check for undefined/null before accessing properties
  if (!row || !Array.isArray(row.sections) || row.sections.length === 0) return false;
  const firstSection = row.sections[0];
  if (!firstSection || !Array.isArray(firstSection.columns)) return false;

  // If a full-size widget is already placed in this 1-column section,
  // do not allow adding a side section (row must remain single-section).
  const hasFullWidget = firstSection.columns.some((col) =>
    Array.isArray(col.widgets) && col.widgets.some((w) => getWidgetSize(String(w?.defId ?? '')) === 1),
  );
  if (hasFullWidget) return false;

  return (
    firstSection.columns.length === 1 &&
    row.sections.length === 1
  );
}

