async function validateUniqueTemplateLabel(payload: PageBuilderTemplate): Promise<boolean> {
  const plantId = Number(payload.plant);
  const label = String(payload.label ?? '').trim();
  const currentId = payload.id ? String(payload.id) : '';

  // If we can't validate properly, skip blocking here.
  if (!label || !Number.isFinite(plantId) || plantId <= 0) return true;

  try {
    const templates = await getTemplatesByPlant(plantId);
    const normalized = label.toLowerCase();
    const duplicate = templates.some((t) => {
      const otherLabel = String(t.label ?? '').trim().toLowerCase();
      const otherId = t.id ? String(t.id) : '';
      if (!otherLabel) return false;
      if (currentId && otherId && otherId === currentId) return false;
      return otherLabel === normalized;
    });

    if (duplicate) {
      notify?.error({
        title: $t('PAGE_BUILDER_VALIDATION'),
        message: $t('PAGE_BUILDER_TEMPLATE_NAME_ALREADY_EXISTS'),
      });
      return false;
    }

    return true;
  } catch (err) {
    console.error('Failed to validate template label uniqueness', err);
    notify?.error({
      title: $t('ERROR'),
      message: $t('PAGE_BUILDER_FAILED_TO_VALIDATE_TEMPLATE_NAME_UNIQUENESS'),
    });
    return false;
  }
}

