async function onSaveDraft(): Promise<void> {
  const nowIso = new Date().toISOString();
  const userName = getUsernameFromProfile(userStore.profile as unknown);

  const payload: PageBuilderTemplate = applyAutoGeneratedNames({
    ...templateStore.template,
    createdAt: templateStore.template.createdAt || nowIso,
    createdBy: templateStore.template.createdBy || userName,
    default: templateStore.template.default ?? false,
    id: templateStore.template.id,
    status: 'draft',
    updatedAt: nowIso,
    updatedBy: userName,
  });

  const validation = validatePreview(payload);
  if (!validation.valid) {
    const message = validation.messageKey
      ? $t(validation.messageKey, validation.messageParams || {})
      : validation.message ||
        $t('PAGE_BUILDER_FIX_TEMPLATE_ERRORS_BEFORE_SAVE');
    notify?.error({
      message,
      title: $t('PAGE_BUILDER_CANNOT_SAVE_DRAFT'),
    });
    return;
  }

  const uniqueOk = await validateUniqueTemplateLabel(payload);
  if (!uniqueOk) return;

  templateStore.setTemplate(payload);
  try {
    const result = await templateStore.saveTemplate();
    if (result.success) {
      notify?.success({
        message: $t('PAGE_BUILDER_TEMPLATE_SAVED_AS_DRAFT'),
        title: $t('PAGE_BUILDER_SAVED'),
      });
      router.replace({ name: 'PageBuilderTemplateList' });
    } else {
      notify?.error({
        message: $t('PAGE_BUILDER_FAILED_TO_SAVE_TEMPLATE_AS_DRAFT'),
        title: $t('ERROR'),
      });
    }
  } catch (err) {
    console.error('Failed to save template as draft', err);
    notify?.error({
      message: $t('PAGE_BUILDER_FAILED_TO_SAVE_TEMPLATE_AS_DRAFT'),
      title: $t('ERROR'),
    });
  }
}

