/**
 * Reorders sections while dragging over other sections.
 * This makes the target "make room" during the drag.

code_excerpt:
function onSectionDragOver(event: DragEvent, targetSectionId: string): void {
  if (!sectionDragData.value) return;

  event.preventDefault();

  const draggedSectionId = sectionDragData.value.sectionId;
  if (draggedSectionId === targetSectionId) return;

  const nextSections = [...sections.value];
  const fromIndex = nextSections.findIndex((s) => s.id === draggedSectionId);
  let toIndex = nextSections.findIndex((s) => s.id === targetSectionId);
  if (fromIndex === -1 || toIndex === -1) return;
  if (fromIndex === toIndex) return;

  // If the target is part of a grouped (side-by-side) row, treat the whole group as one target.
  const target = nextSections[toIndex];
  const targetSideGroupId = String((target as { sideGroupId?: unknown })?.sideGroupId ?? '').trim();
  if (targetSideGroupId) {
    while (
      toIndex > 0 &&
      String((nextSections[toIndex - 1] as { sideGroupId?: unknown })?.sideGroupId ?? '').trim() === targetSideGroupId
    ) {
      toIndex -= 1;
    }
  }

  const [moved] = nextSections.splice(fromIndex, 1);
  if (!moved) return;

  const insertIndex = fromIndex < toIndex ? toIndex - 1 : toIndex;
  nextSections.splice(insertIndex, 0, moved);
  sections.value = nextSections;
  sectionDragData.value.didReorder = true;
}

