function autoResizeInput(
  input: HTMLInputElement | null,
  value: string,
  id: string,
): void {
  if (!input) return;

  const spanId = `auto-width-span-${id}`;
  const spanSelector = `#${spanId}`;

  let span = document.querySelector<HTMLSpanElement>(spanSelector);

  if (!span) {
    span = document.createElement('span');
    span.id = spanId;
    span.style.visibility = 'hidden';
    span.style.position = 'absolute';
    span.style.whiteSpace = 'pre';
    span.style.fontSize = '16px';
    span.style.fontWeight = '700';
    span.style.fontFamily =
      "Arimo, system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif";
    document.body.append(span);
  }

  span.textContent = value || input.placeholder || '';
  const width = Math.max(80, Math.min(400, span.offsetWidth + 24));

  const inputElement = input;
  inputElement.style.width = `${width}px`;
}

