  scopeIds: Array<string>,
  row: UiRow,
): Array<ScopeConflict> {
  const selected = new Set(
    scopeIds.map((x) => String(x).trim()).filter((x) => x.length > 0),
  );
  if (selected.size === 0) return [];

  const scopeType = resolveSelectionMode(row);
  const activeScreenId = resolveActiveScreenId(row.raw.screens);
  const conflictsByScope = new Map<string, ScopeConflict>();

  for (const other of rows.value) {
    const isCurrent = String(other.id) === String(row.id);
    const matchesScreen =
      resolveActiveScreenId(other.raw.screens) === activeScreenId;
    if (isCurrent || !isPublishedRow(other) || !matchesScreen) {
      // Skip current template and non-published templates.
    } else {
      const otherIds = (other.raw.scopeList ?? [])
        .filter((s) => String(s?.scopeType ?? '').toUpperCase() === scopeType)
        .map((s) => String(s?.scopeValue ?? ''))
        .filter((x) => x.trim().length > 0);

      for (const id of otherIds) {
        if (selected.has(id) && !conflictsByScope.has(id)) {
          conflictsByScope.set(id, {
            scopeType,
            scopeValue: id,
            templateLabel: other.label || $t('PAGE_BUILDER_ANOTHER_TEMPLATE'),
          });
        }
      }
    }
  }

  return [...conflictsByScope.values()];
}

