async function confirmAssignConflict(
  conflicts: Array<ScopeConflict>,
  selectionMode: 'RESOURCE' | 'GAP',
): Promise<boolean> {
  assignWarningTitle.value =
    selectionMode === GAP_SCOPE_TYPE
      ? $t('PAGE_BUILDER_SCOPE_CONFLICT_TITLE_GAP')
      : $t('PAGE_BUILDER_SCOPE_CONFLICT_TITLE_RESOURCE');

  const uniqueScopeIds = [
    ...new Set(
      conflicts
        .map((x) => getScopeDisplayLabel(x.scopeValue, selectionMode))
        .filter((x) => x.trim().length > 0),
    ),
  ];
  const uniqueTemplateLabels = [
    ...new Set(
      conflicts.map((x) => x.templateLabel).filter((x) => x.trim().length > 0),
    ),
  ];

  let objectWord = $t('PAGE_BUILDER_SCOPE_CONFLICT_RESOURCE_PLURAL');
  if (selectionMode === GAP_SCOPE_TYPE) {
    objectWord =
      uniqueScopeIds.length === 1
        ? $t('PAGE_BUILDER_SCOPE_CONFLICT_GAP_SINGLE')
        : $t('PAGE_BUILDER_SCOPE_CONFLICT_GAP_PLURAL');
  } else if (uniqueScopeIds.length === 1) {
    objectWord = $t('PAGE_BUILDER_SCOPE_CONFLICT_RESOURCE_SINGLE');
  }
  const objectVerb =
    uniqueScopeIds.length === 1
      ? $t('PAGE_BUILDER_SCOPE_CONFLICT_VERB_SINGLE')
      : $t('PAGE_BUILDER_SCOPE_CONFLICT_VERB_PLURAL');
  const templateWord =
    uniqueTemplateLabels.length === 1
      ? $t('PAGE_BUILDER_SCOPE_CONFLICT_TEMPLATE_SINGLE')
      : $t('PAGE_BUILDER_SCOPE_CONFLICT_TEMPLATE_PLURAL');

  const objectsText = uniqueScopeIds.map((id) => `"${id}"`).join(', ');
  const templatesText = uniqueTemplateLabels
    .map((label) => `"${label}"`)
    .join(', ');

  assignWarningDescription.value =
    uniqueTemplateLabels.length > 0
      ? $t('PAGE_BUILDER_ASSIGN_CONFLICT_DESCRIPTION_WITH_TEMPLATES', {
          objectVerb,
          objectWord,
          objectsText,
          templateWord,
          templatesText,
        })
      : $t('PAGE_BUILDER_ASSIGN_CONFLICT_DESCRIPTION_WITHOUT_TEMPLATES', {
          objectVerb,
          objectWord,
          objectsText,
        });
  assignWarningOpen.value = true;

  return new Promise<boolean>((resolve) => {
    assignWarningResolve.value = (confirmed: boolean) => {
      assignWarningOpen.value = false;
      resolve(confirmed);
    };
  });
}

