async function persistAssignment(scopeIds: Array<string>): Promise<void> {
  const row = assignRow.value;
  const plantId = resolvedPlantId.value;
  if (!row || !Number.isFinite(plantId)) return;
  const scopeType = resolveSelectionMode(row);

  // If assigning scopes to a published template, warn when a selected resource is already
  // Used in another published template.
  if (isPublishedRow(row)) {
    const conflicts = findPublishedScopeConflicts(scopeIds, row);
    if (conflicts.length > 0) {
      const confirmed = await confirmAssignConflict(conflicts, scopeType);
      if (!confirmed) return;
    }
  }

  try {
    const next: TemplateDto = {
      ...row.raw,
      id: row.raw.id || row.id,
      plant: row.raw.plant ?? plantId,
      scopeList: scopeIds.map((id) => ({
        scopeType,
        scopeValue: String(id),
      })),
    };

    await upsertTemplate(next);
    await fetchTemplates();
    notify?.success({
      title: $t('PAGE_BUILDER_SUCCESS'),
      message: $t('PAGE_BUILDER_SCOPE_ASSIGNED_SUCCESSFULLY'),
    });
  } catch {
    notify?.error({
      title: $t('ERROR'),
      message: $t('PAGE_BUILDER_FAILED_TO_ASSIGN_SCOPE'),
    });
  }
}

