async function onPreview(row: UiRow): Promise<void> {
  const plantId = resolvedPlantId.value;
  if (!Number.isFinite(plantId) || plantId === 0) {
    notify?.warning({
      title: $t('WARNING'),
      message: $t('PAGE_BUILDER_PLANT_NOT_SELECTED'),
    });
    return;
  }

  try {
    // Preview from list DTO (avoid broken getTemplate API)
    const dto: TemplateDto = {
      ...row.raw,
      id: row.raw.id || row.id,
      plant: row.raw.plant ?? plantId,
      label: row.raw.label ?? row.label ?? '',
      scopeList: Array.isArray(row.raw.scopeList) ? row.raw.scopeList : [],
    };

    const builderTemplate = templateStore.buildTemplateFromDto(dto);

    const desktopLayout = builderTemplate.devices?.desktop?.layout;
    const sections = (desktopLayout?.sections ?? []) as Array<Section>;

    const MAX_LAYOUT_ROWS = 4;
    const sectionRows: Array<SectionRow> = [];
    let index = 0;

    while (index < sections.length && sectionRows.length < MAX_LAYOUT_ROWS) {
      const group: Array<Section> = [];
      const groupSideId = sections[index].sideGroupId;
      group.push(sections[index]);
      let nextIndex = index + 1;

      while (
        nextIndex < sections.length &&
        sections[nextIndex].sideGroupId &&
        sections[nextIndex].sideGroupId === groupSideId
      ) {
        group.push(sections[nextIndex]);
        nextIndex += 1;
      }

      sectionRows.push({
        key: group.map((s) => s.id).join('-'),
        sections: group,
        showAddButton: sectionRows.length < MAX_LAYOUT_ROWS - 1,
      });
      index = nextIndex;
    }

    // Set preview data
    previewTemplate.value = builderTemplate as PageBuilderTemplate;
    previewSectionRows.value = sectionRows;
    previewFrameStyle.value = {
      width: `${desktopLayout?.width ?? 788}px`,
      height: `${desktopLayout?.height ?? 929}px`,
    };
    previewOpen.value = true;
  } catch (error) {
    notify?.error({
      title: $t('ERROR'),
      message: $t('PAGE_BUILDER_FAILED_TO_LOAD_TEMPLATE_PREVIEW'),
    });
    console.error('Preview error:', error);
  }
}

