async function onCopy(row: UiRow): Promise<void> {
  const plantId = resolvedPlantId.value;
  if (!Number.isFinite(plantId) || plantId === 0) {
    notify?.warning({
      title: $t('WARNING'),
      message: $t('PAGE_BUILDER_PLANT_NOT_SELECTED'),
    });
    return;
  }

  try {
    const baseLabel =
      String(row.raw.label ?? row.label ?? '').trim() ||
      $t('PAGE_BUILDER_TEMPLATE_FALLBACK_NAME');
    const copyLabel = `${baseLabel}_copy`;
    // Create the new template
    await upsertTemplate({
      plant: plantId,
      label: copyLabel,
      scopeList: [],
      status: 'draft',
      createdBy: String(userStore.profile || row.raw.createdBy || ''),
      default: false,
      screens: Array.isArray(row.raw.screens) ? row.raw.screens : [],
      devices: row.raw.devices,
    });

    // Refetch all templates
    await fetchTemplates();

    // Find the new row in the list
    const newRow = rows.value.find(
      (r) => r.label === copyLabel && r.status === 'draft',
    );
    if (newRow) {
      // Remove the new row from its current position
      const index = rows.value.findIndex((r) => r.id === newRow.id);
      if (index !== -1) {
        rows.value.splice(index, 1);
      }
      // Find the index of the source row
      const sourceIndex = rows.value.findIndex((r) => r.id === row.id);
      // Insert the new row just after the source row
      if (sourceIndex >= 0) {
        rows.value.splice(sourceIndex + 1, 0, newRow);
      } else {
        // Fallback: push to end if source not found
        rows.value.push(newRow);
      }
    }
    notify?.success({
      title: $t('PAGE_BUILDER_SUCCESS'),
      message: $t('PAGE_BUILDER_TEMPLATE_COPIED_AS_DRAFT'),
    });
  } catch {
    notify?.error({
      title: $t('ERROR'),
      message: $t('PAGE_BUILDER_FAILED_TO_COPY_TEMPLATE'),
    });
  }
}

