function mapHierarchyToTree(data: Array<any>): Array<TreeNodeType> {
  const mapResource = (
    resource: Resource,
    indices: {
      plantIndex: number;
      uapIndex: number;
      productionIndex: number;
      wcIndex: number;
      resourceIndex?: number;
    },
    ids: {
      plantId?: number;
      uapId?: string;
      prodLineId?: string;
      workcenterId?: string;
    },
  ): TreeNodeType => ({
    id: resource.resourceId ?? indices.plantIndex,
    label: resource.resourceName ?? resource.resourceId,
    meta: {
      plantId: ids.plantId ?? indices.plantIndex,
      uapId: ids.uapId ?? indices.uapIndex,
      productionLineId: ids.prodLineId ?? indices.productionIndex,
      workcenterId: ids.workcenterId ?? indices.wcIndex,
      resourceId: resource.resourceId,
    } as ResourceMeta,
    value: resource.resourceId,
  });

  const mapWorkcenter = (
    wc: Workcenter,
    indices: {
      plantIndex: number;
      uapIndex: number;
      productionIndex: number;
      wcIndex: number;
    },
    ids: { plantId?: number; uapId?: string; prodLineId?: string },
  ): TreeNodeType => ({
    id: wc.workcenterId ?? indices.wcIndex,
    label: wc.workcenterDesc,
    children: (wc.resources ?? []).map((r: Resource, resourceIndex: number) =>
      mapResource(
