  nodes: Array<TreeNodeType>,
  resourceId: string,
): TreeNodeType | undefined {
  for (const n of nodes) {
    if (
      (!n.children || n.children.length === 0) &&
      ((n as unknown as { value?: string }).value === resourceId ||
        String(n.id) === resourceId)
    ) {
      return n;
    }
    if (n.children && n.children.length > 0) {
      const found = findResourceNode(n.children, resourceId);
      if (found) return found;
    }
  }
  return undefined;
}

