const updateRows = (workcenter: Workcenter | WorkcenterResponse | null) => {
  if (!workcenter) return;

  // Common fields
  const commonFieldMappings = {
    workcenterId: 'WORKCENTER_ID',
    plant: 'PLANT',
  };

  // Optional fields
  const extraFieldMappings: Record<string, string> = {};

  if ('workcenterDesc' in workcenter)
    extraFieldMappings.workcenterDesc = 'WORKCENTER_DESC';
  if ('prodLineId' in workcenter)
    extraFieldMappings.prodLineId = 'PROD_LINE_ID';
  if ('advancePickingDuration' in workcenter)
    extraFieldMappings.advancePickingDuration = 'ADVANCE_PICKING_DURATION';
  if ('ewmFlow' in workcenter) extraFieldMappings.ewmFlow = 'EWM_FLOW';

  if ('alertCreation' in workcenter)
    extraFieldMappings.alertCreation = 'ALERT_CREATION';

  // Force inclusion of isMes
  extraFieldMappings.isMes = 'IS_MES';

  const allFields = { ...commonFieldMappings, ...extraFieldMappings };
  const getRowActualValue = (fieldKey: string): RowType['actualValue'] => {
    if (fieldKey === 'isMes') return isMes.value;

    const value = workcenter[fieldKey as keyof typeof workcenter];

    if (
      typeof value === 'string' ||
      typeof value === 'number' ||
      typeof value === 'boolean' ||
      value === null
    ) {
      return value;
    }

    return null;
  };

  rows.value = Object.entries(allFields).map(([key, label]) => {
    return {
      actualValue: getRowActualValue(key),
      key,
      labelKey: label,
      newValue: null,
      parameter: label,
    };
  });

  isEwm.value =
    'ewmFlow' in workcenter ? (workcenter as Workcenter).ewmFlow : isEwm.value;
  isMes.value =
    'isMes' in workcenter
      ? (workcenter as WorkcenterResponse).isMes
      : (isMes.value ?? false);
  alertCreation.value =
    'alertCreation' in workcenter
      ? (workcenter as Workcenter).alertCreation || 'MANUAL'
      : 'MANUAL';
};

