const findSupportUrl = (items) => {
  if (!items || items.length === 0) return null;

  const currentPath = normalizeSupportLookupPath(currentRoute.value);

  const findExactMatch = (items) => {
    for (const item of items) {
      if (
        item.link &&
        item.supportPageUrl &&
        normalizeSupportLookupPath(item.link) === currentPath
      ) {
        return item.supportPageUrl;
      }
      if (item.children && item.children.length > 0) {
        const childMatch = findExactMatch(item.children);
        if (childMatch) return childMatch;
      }
    }
    return null;
  };

  const findBestMatch = (items) => {
    let bestMatch = { item: null, matchCount: 0, matchQuality: 0 };

    const findMatch = (items) => {
      for (const item of items) {
        if (item.link && item.supportPageUrl) {
          const itemPath = normalizeSupportLookupPath(item.link);

          if (currentPath.startsWith(itemPath)) {
            const matchQuality = itemPath.length;

            if (matchQuality > bestMatch.matchQuality) {
              bestMatch = { item, matchCount: 1, matchQuality };
            }
          }
        }

        if (item.children && item.children.length > 0) {
          findMatch(item.children);
        }
      }
    };

    findMatch(items);

    return bestMatch.item?.supportPageUrl || null;
  };

  const result = properties.showFilter
    ? findBestMatch(items)
    : findExactMatch(items);
  return result;
};

