const fetchData = async (ticket: TicketDetails) => {
  Ticket.value = ticket;
  const { dataFetched } = classificationTableStore;
  // Ensure we have a stable background even if the component got recreated
  sendingColor.value =
    classificationTableStore.activeBackground || 'bg--default';

  // Load level-1 causes; on failure keep the last cached values from the persisted store
  try {
    causeDescriptions.value = await api.getDownTimeCauseListByLevel(plant, '1');
    const mapped = causeDescriptions.value
      .slice(0, 5)
      .map((cause: DownTimeCause) => cause['cause desc'] || '')
      .filter((desc) => desc !== '');

    if (mapped.length > 0) {
      classificationTableStore.level1CauseDescriptions = mapped;
    }
  } catch (error) {
    console.error('Error fetching level 1 causes:', error);
  }

  if (Ticket.value) {
    StartDate.value = formatDate(
      Ticket.value.startDate.split('T')[0].split('.')[0],
    );
    StartTime.value = Ticket.value.startDate.split('T')[1].split('.')[0];
    EndDate.value = Ticket.value.endDate
      ? formatDate(Ticket.value.endDate.split('T')[0].split('.')[0])
      : '';
    EndTime.value = Ticket.value.endDate
      ? Ticket.value.endDate.split('T')[1].split('.')[0]
      : '00:00:00';
    remark.value = Ticket.value.remark || '';
    if (!dataFetched || route.query.fromLevel3) {
      classificationTableStore.causeDesc =
        classificationTableStore.causeDesc || Ticket.value.causeDesc || '';
      classificationTableStore.causeDesc1 =
        classificationTableStore.causeDesc1 || Ticket.value.causeDesc1 || '';
      classificationTableStore.causeDesc2 =
        classificationTableStore.causeDesc2 || Ticket.value.causeDesc2 || '';
      classificationTableStore.modifiedBy = Ticket.value.modifiedBy || '';
      classificationTableStore.previousClassificationMode =
        Ticket.value.mode || '';
    }

    classificationTableStore.dataFetched = true;
    // Mark data as fetched
    if (Ticket.value.lockStatus) {
      loadingSaveButton.value = true;
      notify?.warning({
        title: t('IN_PROCESS'),
        message: t('TICKET_IS_BEING_PROCESSED'),
      });
    } else {
      loadingSaveButton.value = false;
    }
  }
};

