  const causeDescription = getCauseDescription(selectedCause);
  const causeCode = getCauseCode(selectedCause, fallbackCauseCode);
  const causeGlobal = getCauseGlobal(selectedCause, fallbackCauseCode);
  const parentCause = getParentCause(selectedCause, fallbackCauseCode);
  const colorClass = getCauseBackgroundClass(causeCode);
  sendingColor.value = colorClass;
  classificationTableStore.activeBackground = colorClass;
  classificationTableStore.causeColor = colorClass;
  $q.loading.show();
