    return Number.isNaN(timestamp) ? Number.NaN : timestamp;
  };

  const getRowTimestamp = (row: TableRow): number => {
    const startDate = (row.startDate || '').trim();
    const startTime = (row.startTime || '').trim();
    const dateTimeCandidates = [
      startDate && startTime ? `${startDate}T${startTime}` : '',
      startDate && startTime ? `${startDate} ${startTime}` : '',
      startDate,
      row.updatedAt,
      row.createdAt,
    ];

    for (const candidate of dateTimeCandidates) {
      const timestamp = parseTimestamp(candidate);
      if (!Number.isNaN(timestamp)) {
        return timestamp;
      }
    }

    return 0;
  };

  const sortedTickets = [...ticketsToClassify.value].sort((a, b) => {
    return getRowTimestamp(b) - getRowTimestamp(a);
  });

  const mostRecentTicket = sortedTickets[0];

  if (mostRecentTicket) {
    goToTicketDetails(mostRecentTicket);
  }
}

