const fetchCauseList = async (labelValue: string, cause: number) => {
  let causeGlobal;
  let level;
  let parentCause;
  try {
    classificationTableStore.currentClassificationMode = '1';
    switch (cause) {
      case 1: {
        level = '2';
        causeGlobal = 1;
        parentCause = '1';
        break;
      }
      case 2: {
        level = '2';
        causeGlobal = 2;
        parentCause = '2';
        break;
      }
      case 3: {
        level = '2';
        causeGlobal = 3;
        parentCause = '3';
        cause = cause;
        break;
      }
      case 4: {
        level = '2';
        causeGlobal = 4;
        parentCause = '4';
        break;
      }
      case 5: {
        level = '2';
        causeGlobal = 5;
        parentCause = '5';
        break;
      }
    }
    causes = await api.getDownTimeCauseListByLevel(
      plant,
      level,
      causeGlobal,
      parentCause,
    );

    const resourceFamilyAssign = await api.getFamilyByPlantAndResource(
      plant,
      resource,
    );
    const matchingCauses: Array<DownTimeCause> = [];
    // Iterate over causes and check against resourceFamilyAssign
    for (const cause of causes) {
      const familyCause = await api.getFamilyByPlantAndCause(
        cause.cause,
        plant,
      );
      const isResourceWithoutFamily = resourceFamilyAssign.length === 0;
      const isCauseWithoutFamily = familyCause.length === 0;
      if (isResourceWithoutFamily && isCauseWithoutFamily) {
        matchingCauses.push(cause);
      } else {
        // Check if every family in the cause matches a family in the resource
        const hasMatchingFamily = familyCause.some((famCause) =>
          resourceFamilyAssign.some(
            (famResource) => famResource.family === famCause.family,
          ),
        );
        // If there's at least one matching family, add the cause
        if (hasMatchingFamily) {
          matchingCauses.push(cause);
        }
      }
    }
    if (matchingCauses.length > 0) {
      isButtonDisabled.value = false;
      classificationTableStore.imageslvl1 = matchingCauses.map((cause) => ({
        srcurl: cause.url,
        url: cause.url || '',
        cause: cause.cause,
        'cause desc': cause['cause desc'] || '',
      }));
      classificationTableStore.causeDesc = labelValue;

      classificationTableStore.cause = cause.toString();
      router.push('/downtime-ui/classification');
    } else {
      classificationTableStore.cause = cause.toString();
      classificationTableStore.causeDesc = labelValue;
      classificationTableStore.cause1 = '';
      classificationTableStore.cause2 = '';
      classificationTableStore.causeDesc1 = '';
      classificationTableStore.causeDesc2 = '';
      isButtonDisabled.value = true;
    }
  } catch (error) {
    console.error('Error fetching cause list:', error);
  }
};

