function triggerOngoing(response: any, customMessage: string): void {
  const { statusCode, statusMessage } = response;
  loadingRequest.value = true;
  const status = statusCode;
  // We need to get the notification reference
  // Otherwise it will never get dismissed ('ongoing' type has timeout 0)
  const notif = $q.notify({
    position: 'top',
    type: 'ongoing',
    message: customMessage,
  });

  // Simulate delay
  setTimeout(async () => {
    let type = 'negative';
    if (status === 'SUCCESS') {
      type = 'positive';
    } else {
      await fetchData();
    }

    notif({
      type,
      message: statusMessage,
      timeout: 3000, // Notification duration
    });

    loadingRequest.value = !loadingRequest.value;
    loadingSaveButton.value = false;
    loadingBackButton.value = false;

    setTimeout(async () => {
      if (status === 'SUCCESS') {
        await redirectTo();
      }
    }, 3000);
  }, 4000);
}

