  customMessage.value =
    'The request of classification of ticket is being treated...';
  if (!validateDatesAndTimes()) {
    return;
  }

  const hasLevel1Selected =
    classificationTableStore.cause !== '' &&
    classificationTableStore.causeDesc !== '';
  const hasLevel2Options =
    (classificationTableStore.imageslvl1?.length ?? 0) > 0;
  const hasLevel3Options =
    (classificationTableStore.imageslvl2?.length ?? 0) > 0;
  const hasLevel2Selected =
    classificationTableStore.cause1 !== '' &&
    classificationTableStore.causeDesc1 !== '';
  const hasLevel3Selected =
    classificationTableStore.cause2 !== '' &&
    classificationTableStore.causeDesc2 !== '';
  const isTerminalSelection = classificationTableStore.backToMain;

  const missingRequiredCause =
    !hasLevel1Selected ||
    (hasLevel2Options && !isTerminalSelection && !hasLevel2Selected) ||
    (hasLevel2Selected &&
      hasLevel3Options &&
      !isTerminalSelection &&
      !hasLevel3Selected);

  if (missingRequiredCause) {
    alertCause.value = true;
    setTimeout(() => {
      alertCause.value = false;
    }, 1500);
  } else {
    alertCause.value = false;
    loadingSaveButton.value = true;
