        classificationTableStore.productionLine = path.productionLine;
        classificationTableStore.workcenter = path.workcenter;
      }
      allData.value = filterDataByResource(allData.value, resource);
    } else if (resourceId && !isValidResourceId) {
      Notify.create({
        message: t('RESOURCE_ID_NOT_FOUND', { resourceId }),
        color: 'warning',
        position: 'top',
        timeout: 3000,
      });
      $q.loading.hide();
      setTimeout(() => {
        router.push('/downtime-ui');
      }, 3000);
      return;
    } else if (
      !resourceId &&
      route.fullPath.endsWith('downtime-screen-details')
    ) {
      Notify.create({
        message: t('RESOURCE_ID_MISSING'),
        position: 'top',
        timeout: 3000,
        type: 'negative',
      });
      router.push('/downtime-ui');
    }

    if (resourceId && isValidResourceId) {
      valueObject.value = resourceId;
    }
