async function performSearch(): Promise<void> {
  const q = searchQuery.value.trim();
  // Empty search should be handled by the watcher above
  if (!q) return;

  try {
    const plant = await getPlant();
    if (!plant) return;

    // Use API to search causes (pass empty resource)
    const res = await getAllDowntimeCauses(plant, '', q);
    // Map server results into the node shape used by the tree
    const nodes = mapResultsToNodes(mapServerResultsToNodes(res || []));

    // Replace the current tree with the search results
    causes.value = nodes;

    // Find the first node (depth-first) whose label or any child's label
    // Contains the search query (case-insensitive) and select it.
    const qLower = q.toLowerCase();

    // Helper to find path (ids) from root to target node
    /**
     *
     */
    function findPathToMatch(): Array<string> | null {
      const path: Array<string> = [];
      let found = false;

      /**
       *
       * @param node
       * @param ancestors
       */
      function dfs(node: CauseNode, ancestors: Array<string>): boolean {
        if (found) return true;
        const label = (node.label || '').toString().toLowerCase();
        if (label.includes(qLower)) {
          path.push(...ancestors, node.id);
          found = true;
          return true;
        }
        if (node.children) {
          for (const child of node.children) {
            if (dfs(child, [...ancestors, node.id])) return true;
          }
        }
        return false;
      }

      for (const root of causes.value) {
        if (dfs(root, [])) break;
      }
      return found ? path : null;
    }

    const path = findPathToMatch();
    if (path && path.length > 0) {
      // Expand all ancestors so the matched node is visible
      const parents = new Set<string>(path.slice(0, -1));
      expandedSet.value = parents;
      // Select the matched (leaf or intermediate) node
      const matchedId = path.at(-1);
      // Use the cause value (which is the id in our mapping)
      if (typeof matchedId === 'string' && matchedId) {
        selectedCause.value = matchedId;
        // Load translations for selected cause
        await selectCause(matchedId);
      } else {
        selectedCause.value = null;
      }
    } else {
      // No exact label match found in mapped nodes; clear selection
      selectedCause.value = null;
      expandedSet.value = new Set<string>();
    }
  } catch (error) {
    console.error('Search failed', error);
  }
}

