async function toggleExpand(node: CauseNode) {
  // Replace the Set reference so Vue detects the change when passed as a prop
  const next = new Set(expandedSet.value);
  const willBeExpanded = !next.has(node.id);
  if (willBeExpanded) next.add(node.id);
  else next.delete(node.id);
  expandedSet.value = next;

  // If we're expanding and children are not loaded yet, fetch them.
  if (willBeExpanded && (!node.children || node.children.length === 0)) {
    const key = node.id;
    try {
      loading[key] = true;
      const plant = await getPlant();
      if (!plant) return;

      // Compute depth of node in the current tree so we can request the next level
      const depth = findDepth(node.cause);
      const nextLevel = String(depth + 1);

      const res = await getDownTimeCauseListByLevel(
        plant,
        nextLevel,
        undefined,
        node.cause,
      );
      const children = mapResultsToNodes(mapServerResultsToNodes(res || []));
      // Assign children (reactive)
      node.children = children;
    } catch (error) {
      console.error('Failed to load children for', node.cause, error);
      node.children = [];
    } finally {
      loading[key] = false;
    }
  }
}

