code_excerpt:
function findDepth(causeId: string): number {
  const queue: Array<{ n: CauseNode; depth: number }> = causes.value.map(
    (n) => ({ n, depth: 1 }),
  );
  while (queue.length > 0) {
    const { n, depth } = queue.shift() as { n: CauseNode; depth: number };
    if (n.cause === causeId) return depth;
    if (n.children && n.children.length > 0) {
      for (const c of n.children) queue.push({ n: c, depth: depth + 1 });
    }
  }
  return 1;
}

