async function submitNewTranslation() {
  if (!selectedCause.value) return;
  try {
    const plant = await getPlant();
    if (!plant) return;
    await addCauseDescription(selectedCause.value, plant, {
      lang: newTranslation.lang,
      translatedDesc: newTranslation.translatedDesc,
