  const input = e.target as HTMLInputElement;
  const file = input?.files?.[0];
  if (!file) return;

  try {
    importInProgress.value = true;
    const plant = await getPlant();
    if (!plant) {
      notify?.error?.({ title: t('ERROR'), message: t('PLANT_NOT_SET') });
      return;
    }

    // Quick pre-validate language codes inside the sheet before sending to backend
    const workbook = new exceljs.Workbook();
    const buffer = await file.arrayBuffer();
    await workbook.xlsx.load(buffer);
    const worksheet = workbook.worksheets[0];
    const rows: Array<Record<string, unknown>> = [];
    if (worksheet) {
      const headerRow = worksheet.getRow(1);
      const headers: Array<string> = [];
      const headerCellCount = headerRow.cellCount ?? 0;
      for (let index = 1; index <= headerCellCount; index += 1) {
        const hv = headerRow.getCell(index).value;
        headers.push(hv == undefined ? '' : String(hv));
      }
      worksheet.eachRow((row: any, rowNumber: number) => {
        if (rowNumber === 1) return;
        const object: Record<string, unknown> = {};
        for (const [index, header] of headers.entries()) {
          const key = header || `col${index + 1}`;
          const { value } = row.getCell(index + 1);
          let cellValue: unknown;
          if (value === undefined) cellValue = null;
          else if (
            typeof value === 'object' &&
            value !== null &&
            'text' in (value as unknown as Record<string, unknown>)
