export function resolveDateTimeInZone(
  rawValue: string,
  zone: string,
): DateTime | undefined {
  const utc = DateTime.fromISO(rawValue, { zone: 'utc' });
  if (utc.isValid) {
    return utc.setZone(zone);
  }

  const zoned = parseIsoInZone(rawValue, zone);
  return zoned.isValid ? zoned : undefined;
}

