    );
    return;
  }

  datadogRum.init({
    applicationId,
    clientToken,
    site,
    service,
    env,
    version: import.meta.env.npm_package_version ?? '0.0.0',

    // Session sampling — adjust as needed (100 = all sessions tracked)
    sessionSampleRate: 100,
    // Session Replay sampling — keep at 0 to avoid recording user screens
    // unless explicitly needed and privacy-reviewed
    sessionReplaySampleRate: 0,

    // Track user interactions (clicks, taps, scrolls)
    trackUserInteractions: true,
    // Track resources (XHR, fetch, etc.) — must be true for RUM–Traces
    // correlation: the SDK injects traceparent headers on tracked resources.
    trackResources: true,
    // Track long-running tasks
    trackLongTasks: true,

    // Allow Datadog to capture action names (button text, element content)
    // so we can track which buttons and elements users interact with.
    // PII is still scrubbed by the beforeSend callback below.
    enablePrivacyForActionName: false,

    // Default privacy level for Session Replay (if ever enabled):
    // 'mask' ensures all text is replaced with asterisks
    defaultPrivacyLevel: 'mask',

    // Proxy: route RUM data through your own server so end-user devices
    // never communicate directly with Datadog (recommended by the docs).
    // Leave DD_PROXY_URL empty to send directly to Datadog.

     ...(proxyUrl ? { proxy: proxyUrl } : {}),

    // Allowed tracing origins — use the OTEL tracecontext propagator so the
    // `traceparent` / `tracestate` headers are injected on every matching request.
    // The backend reads these via its W3CTraceContextPropagator and exports the
    // correlated span to Datadog, enabling end-to-end RUM–APM linking.
    allowedTracingUrls: [
      { match: /https:\/\/mesx-.*\.app\.corp/, propagatorTypes: ['tracecontext'] },
      { match: /http:\/\/localhost/, propagatorTypes: ['tracecontext'] },
    ],

