async function submitGroupComment(hour: string, text?: string): Promise<void> {
  const commentText =
    typeof text === 'string' ? text : editingCommentText.value.trim();
  const originalText = editingOriginalComment.value.trim();

  if (commentText === originalText) return;
  // Allow deleting comment (empty text with existing original)
  if (!commentText && !originalText) return;

  const normalizedHour = normalizeHourKey(hour);
  const previousEditingHour = editingCommentHour.value;
  const previousEditingText = editingCommentText.value;
  const previousOriginalComment = editingOriginalComment.value;
  const previousOptimisticCommentsByHour = {
    ...optimisticGroupCommentsByHour.value,
  };

  optimisticGroupCommentsByHour.value = {
    ...optimisticGroupCommentsByHour.value,
    [normalizedHour]: {
      lastEditedTime: commentText.trim() ? toHourMinute(new Date()) : undefined,
      text: commentText.trim(),
    },
  };

  editingCommentHour.value = undefined;
  editingCommentText.value = '';
  editingOriginalComment.value = '';

  const success = await store.saveGroupComment(hour, commentText);
  if (!success) {
    optimisticGroupCommentsByHour.value = previousOptimisticCommentsByHour;
    editingCommentHour.value = previousEditingHour ?? hour;
    editingCommentText.value = previousEditingText;
    editingOriginalComment.value = previousOriginalComment;
  }
}

