function applySlowdownCommentToGroup(
  group: TimeGroup,
  description: string,
): TimeGroup {
  const text = description.trim();
  const previousSlowdownComment = getGroupSlowdownComment(group)?.trim() ?? '';
  const previousGroupCommentText = group.comment?.text?.trim() ?? '';
  const shouldMirrorGroupComment =
    previousGroupCommentText.length === 0 ||
    previousGroupCommentText === previousSlowdownComment;

  if (!text) {
    return {
      ...group,
      events: group.events.filter(
        (eventItem) => eventItem.category !== 'slowdown',
      ),
      comment: shouldMirrorGroupComment ? undefined : group.comment,
    };
  }

  const hasSlowdown = group.events.some(
    (eventItem) => eventItem.category === 'slowdown',
  );

  if (!hasSlowdown) {
    const nextGroup: TimeGroup = {
      ...group,
      events: [...group.events, createSyntheticSlowdownEvent(group, text)],
    };

    if (!shouldMirrorGroupComment) {
      return nextGroup;
    }

    return {
      ...nextGroup,
      comment: {
        text,
        lastEditedTime: group.comment?.lastEditedTime,
      },
    };
  }

  const nextGroup: TimeGroup = {
    ...group,
    events: group.events.map((eventItem) => {
      if (eventItem.category !== 'slowdown') {
        return eventItem;
