function isAdjacentBoundary(
  previousEndDateTime: string | undefined,
  nextStartDateTime: string | undefined,
): boolean {
  if (!previousEndDateTime || !nextStartDateTime) {
    return false;
  }

  if (previousEndDateTime === nextStartDateTime) {
    return true;
  }

  const previousTimestamp = Date.parse(previousEndDateTime);
  const nextTimestamp = Date.parse(nextStartDateTime);

  if (Number.isNaN(previousTimestamp) || Number.isNaN(nextTimestamp)) {
    return false;
  }

  return previousTimestamp + 1000 === nextTimestamp;
}

