): Array<MappedEventEntry> {
  const configurationItems = Array.isArray(hour.configuration)
    ? hour.configuration
    : [];
  const hasSingleConfigurationItem = configurationItems.length === 1;

  return configurationItems.flatMap((item) => {
    const startDateTime =
      typeof item.dateHourFrom === 'string' ? item.dateHourFrom : undefined;
    const endDateTime =
      typeof item.dateHourTo === 'string' ? item.dateHourTo : undefined;
    const action = typeof item.action === 'string' ? item.action : undefined;
    const time =
      startDateTime && startDateTime.length >= 16
        ? startDateTime.slice(11, 16)
        : undefined;

    if (!action || time === undefined) {
      return [];
    }

    const directDescription =
      typeof item.description === 'string' && item.description.trim()
        ? item.description.trim()
        : undefined;
    const fromAction =
      typeof item.fromAction === 'string' && item.fromAction.trim()
        ? item.fromAction.trim()
        : undefined;
    const description =
      directDescription ?? getConfigurationDescription(fromAction, action);
    let duration: string | undefined;
    if (
      action !== 'N' &&
      typeof item.duration === 'string' &&
      item.duration.trim()
    ) {
      duration = item.duration.trim();
    }

    const event: EventItem = {
      badgeColor: '#DDE5FF',
      badgeTextColor: '#643B48',
      category: 'configuration',
      description,
      descriptionParts: description?.trim()
        ? [{ text: description.trim() }]
        : [],
      duration,
      endDateTime,
      id: `configuration:${startDateTime}:${action}`,
      isOngoing: item.isOngoing === true,
      startDateTime,
      time,
      type: action,
    };

    const mergeKey = fromAction;
    const stateKey = [action, fromAction ?? '', description ?? ''].join('|');
    const isConfigurationContinuationCandidate =
      hasSingleConfigurationItem &&
