/**
 * Maps one hourly API response bucket to an Event Center time group.
 * @param hour The raw hourly API response bucket.

code_excerpt:
function mapHourToGroup(
  hour: EventCenterHistoryHourApiDto,
): MappedTimeGroup | undefined {
  const time =
    hour.dateHourFrom && hour.dateHourFrom.length >= 16
      ? hour.dateHourFrom.slice(11, 16)
      : hour.hour;

  if (time === undefined) {
    return undefined;
  }

  const events = [
    ...mapDowntimeItems(hour),
    ...mapSlowdownItems(hour),
    ...mapChangeProductionItems(hour),
    ...mapConfigurationItems(hour),
    ...mapCommentItems(hour),
    ...mapScrapItems(hour),
    ...mapReworkItems(hour),
  ].sort((left, right) => left.event.time.localeCompare(right.event.time));

  const hourComment = mapHourComment(hour);

  return {
    comment: hourComment,
    events,
    groupEnd: hour.dateHourTo,
    groupStart: hour.dateHourFrom,
    time,
  };
}

