/**
 * Merges matching configuration and downtime events across successive hour groups.
 * @param groups The mapped hour groups to merge.

code_excerpt:
function mergeSuccessiveEvents(
  groups: Array<MappedTimeGroup>,
): Array<TimeGroup> {
  const mergedGroups = groups.map((group) => ({
    ...group,
    events: [...group.events],
  }));
  const previousEventByCategoryAndKey = new Map<string, MergeState>();
  let previousConfigurationState: ConfigurationState | undefined;

  for (const [groupIndex, group] of mergedGroups.entries()) {
    const nextEvents: Array<MappedEventEntry> = [];

    for (const entry of group.events) {
      if (entry.event.category === 'configuration') {
        const configurationStateKey = entry.stateKey;
