function parseSlowdownThresholdMinutes(
  source: Record<string, unknown> | undefined,
): number | undefined {
  if (!source) {
    return undefined;
  }

  const candidateKeys = [
    'slowdownMax',
    'slowdownThreshold',
    'threshold',
    'sdMax',
    'maxSlowdown',
  ] as const;

  for (const key of candidateKeys) {
    const parsedMinutes = parseNonZeroSlowdownMinutes(source[key]);

    if (parsedMinutes !== undefined) {
      return Math.abs(parsedMinutes);
    }
  }

  return undefined;
}

