const handleAssignment = async (data: { gap: string; gapDesc?:string; resources: any[] }) => {
  try {
    store.setAssigning(true)

    const config = getApiConfig()

    const resourceIds = data.resources.map((r) => r.id)

    // Get gap description from mLean gap list (selector)
    const selectedGapData = store.availableGaps.find(
      (gap: GapData) => String(gap.id) === String(data.gap) ,
    )

    // Get gap description from selected resource in hierarchy using store.allResources
    const matchedResource = store.allResources.find(
      (r: Resource) => String(r.gap) === String(data.gap)
    )

    const resourceGapDesc = matchedResource?.gapDesc
    // Priority: Use gapDesc from mLean list, fallback to resource gapDesc, then to gap name, then to gapId
    const gapId = data.gap
    const gapDesc =
      (selectedGapData?.name as string) ||
      resourceGapDesc

    const response = await gapApiService.assignGapToResources(config.plant, resourceIds, gapId, gapDesc)

    store.updateResourcesWithGaps(response.updatedResourceIds, data.gap, gapDesc)

    notify?.success({
      title: t('ASSIGNMENT_SUCCESSFUL'),
      message: t('ASSIGNMENT_SUCCESS_MESSAGE', {
        count: resourceIds.length,
        gap: data.gap,
      }),
    })

    store.unselectAll()
    store.closeAssignmentModal()
  } catch (err) {
   notify?.error({
     title: t('ASSIGNMENT_FAILED'),
     message:
       err instanceof Error ? err.message : t('ASSIGNMENT_FAILED_MESSAGE'),
   })
 } finally {
   store.setAssigning(false)
 }
}

