function mapResponseToMatrix(data: PolyvalenceResponse): void {
  const mappedRows: Array<MatrixRow> = data.rows.map((row) => {
    const operationsValues = data.columns.map((column) => {
      const matchingCell = row.cells.find(
        (cell) => cell.operatorId === column.operatorId,
      );
      return toCellValue(matchingCell);
    });

    const score = operationsValues.filter(isValidatedLevel).length;
    const status = score >= VALIDATED_U_THRESHOLD ? 'ok' : 'ko';

    return {
      id: `workstation-${row.workstationId}`,
      workstation: row.workstationName,
      reference: `Workstation ID: ${row.workstationId}`,
      score,
      status,
      operations: operationsValues,
    };
  });

  const mappedOperations: Array<OperationHeader> = data.columns.map(
    (column) => {
      const score = mappedRows.reduce((total, row) => {
        const rowValue = row.operations.find((_, index) => {
          const currentColumn = data.columns[index];
          return currentColumn?.operatorId === column.operatorId;
        });
        return total + (rowValue && isValidatedLevel(rowValue) ? 1 : 0);
      }, 0);

      return {
        id: `operator-${column.operatorId}`,
        label: column.operatorName,
        score,
        status: score >= VALIDATED_U_THRESHOLD ? 'ok' : 'ko',
      };
    },
  );

  operations.value = mappedOperations;
  matrixRows.value = mappedRows;
}

