  const y = ((event.clientY - rect.top) / rect.height) * 120;
  const dx = x - 60;
  const dy = y - 60;
  const distance = Math.hypot(dx, dy);

  if (distance > 60) return;

  const angleDeg = ((Math.atan2(dy, dx) * 180) / Math.PI + 360) % 360;
  const angleFromTopDeg = (angleDeg + 90) % 360;

  const okAngle = (okCount.value / totalCount.value) * 360;
  const nokAngle = okAngle + (nokCount.value / totalCount.value) * 360;
  if (angleFromTopDeg < okAngle) {
    selectedFilter.value = 'OK';
  } else if (angleFromTopDeg < nokAngle) {
    selectedFilter.value = 'NOK';
  } else {
    selectedFilter.value = 'gray';
  }
}

