async function loadRoutineData(teamOverride?: string): Promise<void> {
  const effectiveTeam = teamOverride ?? properties.team;

  if (!properties.plant || !effectiveTeam?.trim()) {
    cards.value = [];
    error.value = undefined;
    updateMleanButtonHref('');
    return;
  }

  const currentShift = dashboardStore.shiftInfo?.currentShift;
  if (!currentShift) {
    error.value = t('ROUTINE_ERROR_NO_SHIFT');
    return;
  }

  isLoading.value = true;
  error.value = undefined;

  try {
    const profileStore = useProfileStore();
    const timezone = profileStore.userAttributes?.timezone;
    const apiResponse = await fetchRoutineDetails({
      plant: properties.plant,
      shiftEndDate: currentShift.endDatetime,
      shiftStartDate: currentShift.startDatetime,
      team: effectiveTeam,
      timezone: timezone || undefined,
    });

    cards.value = transformApiResponseToRoutineCards(apiResponse);
    updateMleanButtonHref(effectiveTeam);
  } catch (error_) {
    const errorMessage =
      error_ instanceof Error ? error_.message : t('ROUTINE_ERROR_LOAD_FAILED');
    error.value = errorMessage;
    notify?.error({
      message: errorMessage,
      title: t('ERROR'),
    });
  } finally {
    isLoading.value = false;
  }
}

