function buildSlotTimelineSegments(
  status: string,
  shiftHours: number,
  options?: MapResourcesToCardsOptions,
): string[] {
  if (!status || status.trim() === '') {
    return Array.from({ length: shiftHours * 12 }, () => statusCodeToColor(6));
  }

  const statusTokens = status.split(';');
  if (statusTokens.length === 0) {
    return Array.from({ length: shiftHours * 12 }, () => statusCodeToColor(6));
  }

  const shiftStartMs = options?.shiftStartDate
    ? new Date(options.shiftStartDate).getTime()
    : Number.NaN;
  const hasShiftStart = Number.isFinite(shiftStartMs);
  const nowMs = getCurrentTimeInTimezone(options?.timezone).getTime();
  const slotDurationMs = 5 * 60 * 1000;

  return statusTokens.map((slotToken, slotIndex) => {
    const trimmed = slotToken.trim();
    if (trimmed === '') {
      if (!hasShiftStart) {
        return 'transparent';
      }

      const slotStartMs = shiftStartMs + slotIndex * slotDurationMs;
      return slotStartMs < nowMs ? statusCodeToColor(0) : 'transparent';
    }
    return statusCodeToColor(statusTokenToCode(trimmed));
  });
}

