export function mapResourceToCard(
  resource: ResourceApiResponse,
  options?: MapResourcesToCardsOptions,
): ResourceCardData {
  const shiftHours = computeShiftHours(options?.shiftStartDate, options?.shiftEndDate);

  const kpis: ResourceCardKpi[] = [
    {
      label: 'TARGET',
      value: Math.round(resource.shiftTotals.target),
    },
    {
      label: 'PRODUCED',
      value: resource.shiftTotals.production,
    },
    {
      label: 'DELTA',
      value: Math.round(resource.shiftTotals.delta),
      color: resource.shiftTotals.delta < 0 ? '#C10015' : '#21BA45',
      bgColor: resource.shiftTotals.delta < 0 ? '#C10015' : '#21BA45',
    },
    {
      label: 'SCRAP',
      value: resource.shiftTotals.scrap,
    },
  ];

  const timelineSegments = buildSlotTimelineSegments(
    resource.status,
    shiftHours,
    options,
  );
  const timelineProgressPercent = computeTimelineProgressPercent(
    options?.shiftStartDate,
    options?.shiftEndDate,
    options?.timezone,
  );
  const lastNonTransparent = [...timelineSegments].reverse().find((c) => c !== 'transparent');
  const lastTimelineColor = lastNonTransparent ?? statusCodeToColor(6);
  const headerTextColor = getHeaderTextColor(lastTimelineColor);

  return {
    id: resource.resourceId,
    name: resource.resourceName,
    kpis,
    borderColor: lastTimelineColor,
    headerBgColor: lastTimelineColor,
    headerTextColor,
    timelineSegments,
    timelineProgressPercent,
  };
}

