export function determineBorderColor(statusColors: string[]): string {
  if (statusColors.length === 0) {
    return statusCodeToColor(6);
  }

  const prodCount = statusColors.filter(c => c === statusCodeToColor(0)).length;
  const issueCount = statusColors.filter(
    c => c === statusCodeToColor(4) || c === statusCodeToColor(5),
  ).length;
  const totalCount = statusColors.length;

  if (issueCount > 0) {
    return statusCodeToColor(4);
  }

  if (prodCount > totalCount * 0.7) {
    return '#21ba45'; // Production green
  }

  return statusCodeToColor(6);
}

