async function resolveHierarchyByGapId(
  targetGapId: string,
): Promise<GapHierarchyContext | undefined> {
  if (!targetGapId) {
    return undefined;
  }

  const cachedContext = gapHierarchyCache.value[targetGapId];
  if (cachedContext) {
    return cachedContext;
  }

  try {
    const hierarchy = await hierarchyService.getHierarchy();
    const gapTree = HierarchyService.transformApiToGapResourceTree(hierarchy);

    const matchingGap = gapTree.find((node) => String(node.value) === targetGapId);
    if (!matchingGap) {
      return undefined;
    }

    const firstChild = matchingGap.children?.[0];
    const resolvedContext: GapHierarchyContext = {
      plant: String(matchingGap.meta?.plantId ?? firstChild?.meta?.plantId ?? '').trim(),
      resource: String(firstChild?.meta?.resourceId ?? firstChild?.value ?? '').trim(),
      workcenter: String(firstChild?.meta?.workcenterId ?? '').trim(),
      resourceCount: matchingGap.children?.length ?? 0,
    };

    if (!resolvedContext.plant || !resolvedContext.workcenter) {
      return undefined;
    }

    gapHierarchyCache.value[targetGapId] = resolvedContext;
    return resolvedContext;
  } catch (error) {
    console.warn('Failed to resolve plant from hierarchy for gap:', targetGapId, error);
    return undefined;
  }
}

