    if (requestGapId && hierarchyStore.gapId !== requestGapId) {
      hierarchyStore.setGapId(requestGapId);
    }

    if (requestGapId) {
      const { plant: resolvedPlant, shouldReturn } =
        await handleHierarchyResolution(requestGapId);
      if (shouldReturn) return;
      requestPlant = resolvedPlant;
    }

    const shiftContext = await ShiftApiService.getShiftInfo();
    const { startDate, endDate } = await loadShiftAndUpdateDates(shiftContext);

    if (startDate && endDate) {
      requestShiftStartDate = startDate;
      requestShiftEndDate = endDate;
    }

    if (!requestPlant && shiftContext?.plant !== undefined) {
      requestPlant = String(shiftContext.plant).trim();
    }

    if (!requestGapId || !requestPlant || !requestShiftStartDate || !requestShiftEndDate) {
