function buildBalancingWindowEndTimestamp(
  currentShift?: ShiftContextSlice,
  previousShift?: ShiftContextSlice,
  previousPreviousShift?: ShiftContextSlice,
): number | undefined {
  if (!currentShift?.startDatetime) return undefined;

  const currentStart = new Date(currentShift.startDatetime);
  if (Number.isNaN(currentStart.getTime())) return undefined;

  const lastShiftEndTime = [
    currentShift.endDatetime,
    previousShift?.endDatetime,
    previousPreviousShift?.endDatetime,
  ]
    .map((value) => getMillisecondsFromTimePart(value))
    .filter((value): value is number => value !== undefined)
    .sort((left, right) => right - left)[0];

  if (lastShiftEndTime === undefined) return undefined;

