function handleRowClick(event: Event, row: ShiftRowData, _index: number) {
  // Find the clicked cell
  let cell = event?.target as HTMLElement;
  while (cell && cell.tagName !== 'TD' && cell !== event.currentTarget) {
    cell = cell.parentElement as HTMLElement;
  }
  if (!cell || cell === event.currentTarget) return;

  // Get column name from cell class
  const classList = [...cell.classList];
  const colClass = classList.find((c) => c.endsWith('-cell'));
  if (colClass) {
    const colName = colClass.replace('-cell', '');
    if (EXCLUDED_COLUMNS.has(colName)) return;
    if (colName === 'uc-ticket' && (row.ucTicket ?? 0) > 0) return;
    if (colName === 'comments' && getVisibleCommentsCount(row) > 0) return;
    if (colName === 'notification' && getNotificationCount(row) > 0) return;
  }

  openEventCenterForRow(row);
}

