    (notification) =>
      notification.type === 'JIT_RECLASSIFICATION' ||
      notification.type === 'UNCLASSIFIED',
  );

  for (const ticketItem of classificationTickets) {
    classificationItems.push({
      cause: ticketItem.cause,
      causeDescription: ticketItem.causeDescription,
      count: 1,
      hour: row.hour,
      ticket: ticketItem.ticket,
      type: 'CLASSIFICATION',
    });
  }

  const tickets = (row.notifications ?? [])
    .filter((notification) => notification.type === 'DOWNTIME_JUSTIFICATION')
    .map((ticketItem) => ({
      cause: ticketItem.cause,
      causeDescription: ticketItem.causeDescription,
      hour: row.hour,
      ticket: ticketItem.ticket,
      type: 'TICKET' as const,
    }));

  const slowdowns: Array<SlowdownCommentItem> = [];
  const hasSlowdownNotification = (row.notifications ?? []).some(
    (notification) => notification.type === 'SLOWDOWN_JUSTIFICATION',
  );
  const hasRealSlowdown = hasActionableSlowdown(row.slowdown);

  if (hasSlowdownNotification && hasRealSlowdown) {
    slowdowns.push({
      description: row.description,
      duration: row.slowdown,
      hour: row.hour,
      isOverspeed: false,
      type: 'SLOWDOWN',
    });
  }

  return [...classificationItems, ...tickets, ...slowdowns];
}

