async function openBalancingDrawer(): Promise<void> {
  commentsDrawer.value = false;
  balancingDrawer.value = true;
  balancingLoading.value = true;
  balancingOptions.value = undefined;

  const options = timeOptions.value;
  const nowPlant = timezone.value
    ? new Date(new Date().toLocaleString('en-US', { timeZone: timezone.value }))
    : new Date();
  const currentLabel = `${nowPlant.getHours().toString().padStart(2, '0')}:${nowPlant.getMinutes().toString().padStart(2, '0')}`;
  const currentOption =
    options.find((opt) => opt.label === currentLabel) ??
    [...options].reverse().find((opt) => opt.label <= currentLabel) ??
    options[0];
  selectedStart.value = currentOption?.value;
  selectedEnd.value = undefined;
  selectedMode.value = undefined;
  manualOperatorCount.value = undefined;
  manualTarget.value = undefined;

  try {
    const plant =
      hierarchyStore.plant?.toString() ?? profileStore.userAttributes?.plant;
    const resourceId = hierarchyStore.resource;
    if (!plant || !resourceId) {
      notify.error({
        message: t('BALANCING_MISSING_CONTEXT_ERROR'),
        title: t('ERROR'),
      });
      return;
    }

    const availability = await ShiftApiService.getBalancingAvailability({
      plant,
      resourceId,
    });
    balancingEnabled.value = availability?.enabled === true;

    const rawOptions = await ShiftApiService.getBalancingOptions({
      plant,
      resourceId,
      ...(currentShiftCode.value === undefined
        ? {}
        : { shiftCode: String(currentShiftCode.value) }),
    });

    if (rawOptions) {
      balancingOptions.value = rawOptions;
      return;
    }

    const message =
      availability?.enabled === false
        ? t('BALANCING_NOT_CONFIGURED_ERROR')
        : t('BALANCING_OPTIONS_LOAD_ERROR');
    notify.error({ message, title: t('ERROR') });
  } catch {
    notify.error({
      message: t('BALANCING_OPTIONS_LOAD_ERROR'),
      title: t('ERROR'),
    });
  } finally {
    balancingLoading.value = false;
    startBalancingInactivityTimer();
  }
}

