async function submitBalancing(): Promise<void> {
  if (!balancingEnabled.value) return;
  if (!selectedMode.value) return;
  if (!selectedStart.value || !selectedEnd.value) return;
  if (timeRangeError.value) return;

  const plant =
    hierarchyStore.plant?.toString() ?? profileStore.userAttributes?.plant;
  const resourceId = hierarchyStore.resource;
  if (!plant || !resourceId) return;

  balancingLoading.value = true;
  try {
    const result = await ShiftApiService.configureBalancing({
      endDateTime: ShiftApiService.formatDateTime(new Date(selectedEnd.value)),
      mode: selectedMode.value,
      operatorCount: Math.trunc(displayOperatorCount.value),
      plant,
      resourceId,
      startDateTime: ShiftApiService.formatDateTime(
        new Date(selectedStart.value),
      ),
      target: Number(displayTarget.value),
      timezone: profileStore.userAttributes?.timezone,
      writeDateTime: ShiftApiService.formatDateTime(new Date()),
    });

    if (result.success) {
      closeBalancingDrawer();
      notify.success({
        message: t('BALANCING_CONFIGURATION_SAVED_SUCCESS'),
        title: t('SUCCESS'),
      });
      emit('refreshShiftData');
    } else {
      const message = normalizeBalancingMessage(
        result.message ?? t('BALANCING_WRITEBACK_ERROR'),
      );
      balancingError.value = message;
      notify.error({
        message,
        title: t('ERROR'),
      });
    }
  } catch {
    const message = t('BALANCING_WRITEBACK_ERROR');
    balancingError.value = message;
    notify.error({
      message,
      title: t('ERROR'),
    });
  } finally {
    balancingLoading.value = false;
  }
}

