/**
 * Submits a slowdown comment to the backend API
 * @param item - The slowdown item containing duration and description

code_excerpt:
async function submitSlowdown(item: SlowdownCommentItem): Promise<void> {
  const text = commentText.value?.trim() ?? '';
  const existingComment = getSlowdownCommentText(item.description);
  const isAddingComment = !existingComment && text.length > 0;

  if (text === existingComment) {
    return;
  }

  const row = selectedRow.value;
  if (!row?.hour) return;

  try {
    loadingHour.value = row.hour;
    clearInactivityTimer();

    // Call the async write-back function
    const success = await ShiftApiService.writeSlowdownComment({
      comment: text, // The text user wrote
      endDateTime: row.dateHourTo,
      selectedHour: row.hour,
      startDateTime: row.dateHourFrom,
    });
    if (success) {
      const hadSlowdownNotification = (row.notifications ?? []).some(
        (notification) => notification.type === 'SLOWDOWN_JUSTIFICATION',
      );

      if (hadSlowdownNotification && typeof row.comments === 'number') {
        row.comments = Math.max(row.comments - 1, 0);
      }

      row.notifications = (row.notifications ?? []).filter(
        (notification) => notification.type !== 'SLOWDOWN_JUSTIFICATION',
      );
      row.description = text;

      // Force computed consumers to react immediately to the local optimistic update.
      if (selectedRow.value?.hour === row.hour) {
        selectedRow.value = {
          ...row,
        };
      }

      const nextDismissedHours = new Set(dismissedSlowdownHours.value);
      nextDismissedHours.delete(row.hour);
      dismissedSlowdownHours.value = nextDismissedHours;

      commentText.value = '';
      showCommentForm.value = false;
      activeCommentIndex.value = undefined;
      commentsDrawer.value = false;
      clearInactivityTimer();

      loadingHour.value = undefined;

      if (isAddingComment) {
        eventCenterStore.applySlowdownCommentByHour(row.hour, text);
        eventCenterStore
          .loadGroups()
          .then(() => {
            eventCenterStore.applySlowdownCommentByHour(row.hour, text);
          })
          .catch(() => {
            // Keep optimistic state if background sync fails.
          });
      }
    } else {
      console.error('Failed to submit slowdown comment');
    }
  } catch (error) {
    console.error('Error submitting slowdown comment', error);
  } finally {
    loadingHour.value = undefined;
    if (commentsDrawer.value) {
      startInactivityTimer();
    }
  }
}

