function mapApiStatusToIndicatorStatus(
  apiStatus: string,
): ControlIndicatorStatus {
  switch (apiStatus.toLowerCase()) {
    case 'green': {
      return 'valid';
    }
    case 'red': {
      return 'invalid';
    }
    case 'gray':
    case 'grey': {
      return 'pending';
    }
