export function checkResourceIdExists(
  data: Array<unknown>,
  parameterValue: string,
  parameterName = 'resourceId',
): boolean {
  if (data.length === 0) return false;

  const firstItem = data[0];
  if (typeof firstItem !== 'object' || firstItem === null) return false;

  // Check if it's API structure (has uaps property)
  if ('uaps' in firstItem) {
    return searchApiStructure(data, parameterValue, parameterName);
  }

  // Check if it's tree structure (TreeNodeType with id, label, value properties)
  if ('value' in firstItem && 'label' in firstItem) {
    if (parameterName === 'gapId') {
      // For tree structure with gapId, we need to search for nodes with matching gapId meta
      return searchTreeGapId(data as Array<TreeNodeType>, parameterValue);
    }
    return searchTreeStructure(data as Array<TreeNodeType>, parameterValue);
  }

  return false;
}

