export function checkPayloadConsistency(
  customLogger: AppLogger,
  context: JobsLogContext,
  record: CombinedDtoWithIndex,
): boolean {
  customLogger.verbose(`Checking consistency...`, context);
  if (!record) {
    customLogger.verbose(`Error: payload is empty`, context);
    return false;
  }

  const { __source_table: sourceTable, __op: operation } = record;
  if (!sourceTable) {
    customLogger.verbose(`Error: Table source undefined`, context);
    return false;
  }

  if (
    operation === 'd' &&
    sourceTable === 'EKANBAN_TEMP' &&
    typeof record?.POSTING_STATUS === 'string' &&
    record.POSTING_STATUS.toUpperCase() !== 'POSTED'
  ) {
    return true;
  }

  if (!['c', 'u', 'r'].includes(operation ?? '')) {
    customLogger.verbose(`Error: Unknown operation ${operation}`, context);
    return false;
  }

  return true;
}

