export async function ewmContainerValidation(
  customLogger: AppLogger,
  mappedData: ContainerDto,
  ewmPlantCacheService: EwmPlantCacheService,
): Promise<boolean> {
  const context: JobsLogContext = {
    method: 'ewmContainerValidation',
    service: 'validation',
  };

  try {
    const { plant, workcenter, material } = mappedData;

    /*  Validate workcenter for plant */
    const workcenterList = await ewmPlantCacheService.getInMemoryWorkcenters();

    const workcenterExisting =
      workcenterList[plant]?.includes(workcenter) ?? false;

    if (!workcenterExisting) {
      customLogger.verbose(
        `Workcenter ${workcenter} is not defined in the EWM list for plant ${plant}`,
        context,
      );
      return false;
    }

    /*  Validate materials for plant */
    const materialList = await ewmPlantCacheService.getInMemoryMaterials();

    const allowedMaterialsForPlant = materialList[plant] ?? [];

    if (allowedMaterialsForPlant.length === 0) {
      customLogger.verbose(
        `Plant ${plant} has no EWM materials configured → skipping EWM flow`,
        context,
      );
      return false;
    }

    /*  Validate material belongs to this plant */
    if (!allowedMaterialsForPlant.includes(material)) {
      customLogger.verbose(
        `Material ${material} is not EWM for plant ${plant}`,
        context,
      );
      return false;
    }

    return true;
  } catch (error) {
    customLogger.error(
      `Error processing message: ${error.message}`,
      context,
      error.stack,
    );
    return false;
  }
}

