const emitBarEvent = (
  e: MouseEvent,
  bar: GanttBarObject,
  datetime?: string | Date,
  movedBars?: Map<GanttBarObject, { oldStart: string; oldEnd: string }>,
) => {
  switch (e.type) {
    case 'click': {
      emit('click-bar', { bar, e, datetime });
      break;
    }
    case 'mousedown': {
      emit('mousedown-bar', { bar, e, datetime });
      break;
    }
    case 'mouseup': {
      emit('mouseup-bar', { bar, e, datetime });
      break;
    }
    case 'dblclick': {
      emit('dblclick-bar', { bar, e, datetime });
      break;
    }
    case 'mouseenter': {
      initTooltip(bar);
      emit('mouseenter-bar', { bar, e });
      break;
    }
    case 'mouseleave': {
      clearTooltip();
      emit('mouseleave-bar', { bar, e });
      break;
    }
    case 'dragstart': {
      isDragging.value = true;
      emit('dragstart-bar', { bar, e });
      break;
    }
    case 'drag': {
      emit('drag-bar', { bar, e });
      break;
    }
    case 'dragend': {
      isDragging.value = false;
      emit('dragend-bar', { bar, e, movedBars });
      break;
    }
    case 'contextmenu': {
      emit('contextmenu-bar', { bar, e, datetime });
      break;
    }
  }
};

