export default function useBarDragLimit() {
  const { pushOnOverlap } = provideConfig();
  const getChartRows = provideGetChartRows();

  const getBarsFromBundle = (bundle?: string) => {
    const res: Array<GanttBarObject> = [];
    if (bundle != undefined) {
      for (const row of getChartRows()) {
        for (const bar of row.bars) {
          if (bar.ganttBarConfig.bundle === bundle) {
            res.push(bar);
          }
        }
      }
    }
    return res;
  };

  const setDragLimitsOfGanttBar = (bar: GanttBarObject) => {
    if (!pushOnOverlap.value || bar.ganttBarConfig.pushOnOverlap === false) {
      return;
    }
    for (const sideValue of ['left', 'right']) {
      const side = sideValue as 'left' | 'right';
      const { gapDistanceSoFar, bundleBarsAndGapDist } =
        countGapDistanceToNextImmobileBar(bar, 0, side);
      let totalGapDistance = gapDistanceSoFar;
      const bundleBarsOnPath = bundleBarsAndGapDist;
      if (!bundleBarsOnPath) {
        continue;
      }

      for (let index = 0; index < bundleBarsOnPath.length; index++) {
        const barFromBundle = bundleBarsOnPath[index].bar;
        const gapDistribution = bundleBarsOnPath[index].gapDistance;
        const otherBarsFromBundle = getBarsFromBundle(
          barFromBundle.ganttBarConfig.bundle,
        ).filter((otherBar) => otherBar !== barFromBundle);
        for (const otherBar of otherBarsFromBundle) {
          const nextGapDistanceAndBars = countGapDistanceToNextImmobileBar(
            otherBar,
            gapDistribution,
            side,
          );
          const newGapDistance = nextGapDistanceAndBars.gapDistanceSoFar;
          const newBundleBars = nextGapDistanceAndBars.bundleBarsAndGapDist;
          if (
            newGapDistance != undefined &&
            (!totalGapDistance || newGapDistance < totalGapDistance)
          ) {
            totalGapDistance = newGapDistance;
          }
          for (const newBundleBar of newBundleBars) {
            if (
              !bundleBarsOnPath.find(
                (barAndGap) => barAndGap.bar === newBundleBar.bar,
              )
            ) {
              bundleBarsOnPath.push(newBundleBar);
            }
          }
        }
      }
      const barElement = document.getElementById(
        bar.ganttBarConfig.id,
      ) as HTMLElement;
      if (totalGapDistance != undefined && side === 'left') {
        bar.ganttBarConfig.dragLimitLeft =
          barElement.offsetLeft - totalGapDistance;
      } else if (totalGapDistance != undefined && side === 'right') {
        bar.ganttBarConfig.dragLimitRight =
          barElement.offsetLeft + barElement.offsetWidth + totalGapDistance;
      }
    }
    // All bars from the bundle of the clicked bar need to have the same drag limit:
    const barsFromBundleOfClickedBar = getBarsFromBundle(
      bar.ganttBarConfig.bundle,
    );
    for (const barFromBundle of barsFromBundleOfClickedBar) {
      barFromBundle.ganttBarConfig.dragLimitLeft =
        bar.ganttBarConfig.dragLimitLeft;
      barFromBundle.ganttBarConfig.dragLimitRight =
        bar.ganttBarConfig.dragLimitRight;
    }
  };

  // Returns the gap distance to the next immobile bar
  // In the row where the given bar (parameter) is (added to gapDistanceSoFar)
  // And a list of all bars on that path that belong to a bundle
  const countGapDistanceToNextImmobileBar = (
    bar: GanttBarObject,
    gapDistanceSoFar = 0,
    side: 'left' | 'right',
  ) => {
    const bundleBarsAndGapDistribution = bar.ganttBarConfig.bundle
      ? [{ bar, gapDistance: gapDistanceSoFar }]
      : [];
    let currentBar = bar;
    let nextBar = getNextGanttBar(currentBar, side);
    // Left side:
    if (side === 'left') {
      while (nextBar) {
        const currentBarElement = document.getElementById(
          currentBar.ganttBarConfig.id,
        ) as HTMLElement;
        const nextBarElement = document.getElementById(
          nextBar.ganttBarConfig.id,
        ) as HTMLElement;
        const nextBarOffsetRight =
          nextBarElement.offsetLeft + nextBarElement.offsetWidth;
        gapDistanceSoFar += currentBarElement.offsetLeft - nextBarOffsetRight;
        if (nextBar.ganttBarConfig.immobile) {
          return {
            gapDistanceSoFar,
            bundleBarsAndGapDist: bundleBarsAndGapDistribution,
          };
        }
        if (nextBar.ganttBarConfig.bundle) {
          bundleBarsAndGapDistribution.push({
            bar: nextBar,
            gapDistance: gapDistanceSoFar,
          });
        }
        currentBar = nextBar;
        nextBar = getNextGanttBar(nextBar, 'left');
      }
    }
    if (side === 'right') {
      while (nextBar) {
        const currentBarElement = document.getElementById(
          currentBar.ganttBarConfig.id,
        ) as HTMLElement;
        const nextBarElement = document.getElementById(
          nextBar.ganttBarConfig.id,
        ) as HTMLElement;
        const currentBarOffsetRight =
          currentBarElement.offsetLeft + currentBarElement.offsetWidth;
        gapDistanceSoFar += nextBarElement.offsetLeft - currentBarOffsetRight;
        if (nextBar.ganttBarConfig.immobile) {
          return {
            gapDistanceSoFar,
            bundleBarsAndGapDist: bundleBarsAndGapDistribution,
          };
        }
        if (nextBar.ganttBarConfig.bundle) {
          bundleBarsAndGapDistribution.push({
            bar: nextBar,
            gapDistance: gapDistanceSoFar,
          });
        }
        currentBar = nextBar;
        nextBar = getNextGanttBar(nextBar, 'right');
      }
    }
    return {
      gapDistanceSoFar: null,
      bundleBarsAndGapDist: bundleBarsAndGapDistribution,
    };
  };

  const getNextGanttBar = (bar: GanttBarObject, side: 'left' | 'right') => {
    const barElement = document.getElementById(
      bar.ganttBarConfig.id,
    ) as HTMLElement;
    const allBarsInRow =
      getChartRows().find((row) => row.bars.includes(bar))?.bars ?? [];
    let allBarsLeftOrRight = [];
    allBarsLeftOrRight =
      side === 'left'
        ? allBarsInRow.filter((otherBar) => {
            const otherBarElement = document.getElementById(
              otherBar.ganttBarConfig.id,
            ) as HTMLElement;
            return (
              otherBarElement &&
              otherBarElement.offsetLeft < barElement.offsetLeft &&
              otherBar.ganttBarConfig.pushOnOverlap !== false
            );
          })
        : allBarsInRow.filter((otherBar) => {
            const otherBarElement = document.getElementById(
              otherBar.ganttBarConfig.id,
            ) as HTMLElement;
            return (
              otherBarElement &&
              otherBarElement.offsetLeft > barElement.offsetLeft &&
              otherBar.ganttBarConfig.pushOnOverlap !== false
            );
          });
    if (allBarsLeftOrRight.length > 0) {
      return allBarsLeftOrRight.reduce((bar1, bar2) => {
        const bar1Element = document.getElementById(
          bar1.ganttBarConfig.id,
        ) as HTMLElement;
        const bar2Element = document.getElementById(
          bar2.ganttBarConfig.id,
        ) as HTMLElement;
        const bar1Distribution = Math.abs(
          bar1Element.offsetLeft - barElement.offsetLeft,
        );
        const bar2Distribution = Math.abs(
          bar2Element.offsetLeft - barElement.offsetLeft,
        );
        return bar1Distribution < bar2Distribution ? bar1 : bar2;
      }, allBarsLeftOrRight[0]);
    }
    return null;
  };

  return {
    setDragLimitsOfGanttBar,
  };
}

