export default function useTimePositionMapping(
  config: GGanttChartConfig = provideConfig(),
) {
  const { dateFormat, chartSize } = config;
  const { chartStartDayjs, chartEndDayjs, toDayjs, format } =
    useDayjsHelper(config);

  const totalNumberOfMinutes = computed(() => {
    return chartEndDayjs.value.diff(chartStartDayjs.value, 'minutes');
  });

  const mapTimeToPosition = (time: string) => {
    const width = chartSize.width.value;
    console.log('width', width);
    const diffFromStart = toDayjs(time).diff(
      chartStartDayjs.value,
      'minutes',
      true,
    );
    return Math.ceil((diffFromStart / totalNumberOfMinutes.value) * width);
  };

  const mapPositionToTime = (xPos: number) => {
    const width = chartSize.width.value || 0;
    const diffFromStart = (xPos / width) * totalNumberOfMinutes.value;
    return format(
      chartStartDayjs.value.add(diffFromStart, 'minutes'),
      dateFormat.value,
    );
  };

  return {
    mapTimeToPosition,
    mapPositionToTime,
  };
}

