const togglePin = (
  element: { id: string; pinned?: boolean; [key: string]: unknown },
  index: number,
  direction: string,
) => {
  const item = filtredOrder.value[index];

  if (direction === 'up') {
    originalPositions.value.set(element.id, index);
    filtredOrder.value.splice(index, 1);
    filtredOrder.value.unshift(item);
    element.pinned = true;
  } else if (direction === 'down') {
    const originalPos = originalPositions.value.get(element.id);

    filtredOrder.value.splice(index, 1);
    if (originalPos === undefined) {
      filtredOrder.value.push(item);
    } else {
      let insertPos = originalPos;
      const currentPinnedCount = filtredOrder.value.filter(
        (item: { pinned: boolean }) => item.pinned,
      ).length;

      if (insertPos < currentPinnedCount) {
        insertPos = currentPinnedCount;
      }

      filtredOrder.value.splice(
        Math.min(insertPos, filtredOrder.value.length),
        0,
        item,
      );
      originalPositions.value.delete(element.id);
    }

    element.pinned = false;
  }
};

