          )
          .join(',')
      : filterStore.workCentersSelected || null;

    const uap = Array.isArray(filterStore.workCentersSelected)
      ? filterStore.workCentersSelected
          .filter(
            (v: {
              id: string;
              label: string;
              parentId: string | undefined;
              level: number;
            }) => v.level === 0,
          )
          .map((v: { id: string; label: string }) => v.label)
          .join(',')
      : undefined;

    const pickingOrder = Array.isArray(filterStore.pickingOrderSelected)
      ? filterStore.pickingOrderSelected.join(',')
      : filterStore.pickingOrderSelected || null;

    const outboundDelivery = Array.isArray(filterStore.outboundDeliverySelected)
      ? filterStore.outboundDeliverySelected.join(',')
      : filterStore.outboundDeliverySelected || null;

    const material = Array.isArray(filterStore.materialsSelected)
      ? filterStore.materialsSelected.join(',')
      : filterStore.materialsSelected || null;

    const batch = Array.isArray(filterStore.batchSelected)
      ? filterStore.batchSelected.join(',')
      : filterStore.batchSelected || null;

    const queryParameters = {
      customer,
      workCenter,
      uap,
      pickingOrder,
      outboundDelivery,
      material,
      batch,
      destinationTypeList: Array.isArray(filterStore.destTypSelected)
        ? filterStore.destTypSelected.join(',')
        : filterStore.destTypSelected || null,
      customStatusList: Array.isArray(filterStore.custStatusSelected)
        ? filterStore.custStatusSelected.join(',')
        : filterStore.custStatusSelected || null,
      pickingStatusList: Array.isArray(filterStore.pickingStatusSelected)
        ? filterStore.pickingStatusSelected
        : filterStore.pickingStatusSelected || null,
      sourceTypeList: Array.isArray(filterStore.srcTypSelected)
        ? filterStore.srcTypSelected.join(',')
        : filterStore.srcTypSelected || null,
      tpaNumberList,
      filterGroupingOne:
        localStorage.getItem('filterGroupingOne') ?? 'shopOrder',
      filterGroupingTwo:
        localStorage.getItem('filterGroupingTwo') ?? 'destinationType',
      customStartPreparationDate: filterStore.startPreparationTime,
