async function fetchWorkCentersList(): Promise<any> {
  try {
    const data = await apiService.getWorkCentersList(criteriaId);
    const result: Array<FlattenedOption> = [];
    const workcenterListResult: Array<WorkCenter> = [];

    for (const group of data) {
      result.push({
        id: `parent-${group.uapId}`,
        label: group.uapId,
        isParent: true,
      });

      for (const wc of group.workcenters) {
        if (expandedGroups.value.has(group.uapId)) {
          result.push({
            id: wc.wcCode,
            label: wc.wcCode,
            desc: wc.wcDesc,
            isParent: false,
            parentId: group.uapId,
          });
        }
        workcenterListResult.push({
          wcCode: wc.wcCode,
          wcDesc: wc.wcDesc,
        });
      }
    }

    rawWorkcenterData.value = data;
    filterStore.workcenterList = workcenterListResult;
    return result;
  } catch (error) {
    console.error('Error fetching data:', error);
  }
}

