function clusterCriteria(firstItem: ClusterItem, secondItem: ClusterItem): boolean {
  if (!firstItem || !secondItem) return false;
  if (firstItem.type === 'background' || secondItem.type === 'background') return false;

  const bucketTime = getBucketTime();
  const bucketTimeInMs = convertBucketTimeToMs(bucketTime);

  const firstStartTime = new Date(firstItem.start);
  const secondStartTime = new Date(secondItem.start);

  const firstBucketStart = new Date(Math.floor(firstStartTime.getTime() / bucketTimeInMs) * bucketTimeInMs);
  const secondBucketStart = new Date(Math.floor(secondStartTime.getTime() / bucketTimeInMs) * bucketTimeInMs);

  return firstBucketStart.getTime() === secondBucketStart.getTime() && isClusteringEnabled.value;
}

