function createGroupElement(group: Group): HTMLElement | null {
  if (!group) return null;
  const shouldUseCreateGroupElement = levelOne.value === 'shopOrder' || levelTwo.value === 'shopOrder';
  const isCustemer = levelTwo.value === "customer";
  const isShopOrderDoubleGrouping = levelOne.value === 'shopOrder' && levelTwo.value === 'shopOrder';

  function createGhost() {
    const ghost = document.createElement("div");
    ghost.classList.add('group-ghost');
    ghost.innerHTML = `<img src="/lvl-ui/src/assets/media/ghost.png" alt="icon" class="ghost">`;
    return ghost;
  }

  function getDisplayTimes(groupId: string) {
    if (items?.value?.length) {
      const related = items.value.get().filter((it: any) => String(it.group) === String(groupId));
      return {
        total: pickFirstFromRelated(related, 'launcherWaitingTime'),
        min: pickFirstFromRelated(related, 'minLauncherWaitingTime'),
        max: pickFirstFromRelated(related, 'maxLauncherWaitingTime')
      };
    }
    return { total: undefined, min: undefined, max: undefined };
  }

function createGroupTitle(group: Group, groupTitleContainer: HTMLElement) {
    const groupTitle = document.createElement("div");
    groupTitle.classList.add('group-title', 'group-title-pill');

    const isFirstGroupingTpa = levelOne.value === 'tpaNumber';
    let displayValue = group.nestedInGroup || "";

    if (isFirstGroupingTpa && group.tpaCode !== undefined && group.tpaCode !== null) {
      displayValue = group.tpaCode;
    }

    groupTitle.innerHTML = displayValue;
    groupTitle.style.cursor = 'pointer';
    groupTitle.addEventListener('click', (e: Event) => {
      e.stopPropagation();
      openConfigureAlertMode(String(group.wcDesc || group.nestedInGroup || group.id || ''));
    });
    groupTitleContainer.appendChild(groupTitle);
}

  function createActionBtn(totalDisplay: DisplayValue, minDisplay: DisplayValue, maxDisplay: DisplayValue) {
    const actionBtn = document.createElement('button');
    actionBtn.type = 'button';
    actionBtn.className = 'nested-group-btn';
    // Always show min/max if they are numbers, even if total is empty string
    let totalText = (typeof totalDisplay === 'string' && totalDisplay.trim() === '') ? undefined : totalDisplay;
    // If totalText is undefined but min/max are numbers, show NA for total but keep min/max
    actionBtn.textContent = totalText === undefined ? 'NA' : String(totalText);
    actionBtn.title = 'Group actions';
    actionBtn.dataset.groupId = String(group.id || '');
    let badgeColor = '#C10015';
    if (totalText === undefined) {
      actionBtn.classList.add('nested-group-btn-na');
      actionBtn.style.background = '';
      actionBtn.style.color = '';
    } else {
      actionBtn.classList.remove('nested-group-btn-na');
      const totalNum = parseTime(totalText);
      const minNum = parseTime(minDisplay);
      const maxNum = parseTime(maxDisplay);
      if (!Number.isNaN(totalNum) && !Number.isNaN(minNum) && !Number.isNaN(maxNum) && totalNum >= minNum && totalNum <= maxNum) {
        badgeColor = '#43a047';
      }
      actionBtn.style.color = '#fff';
      actionBtn.style.background = badgeColor;
    }
    actionBtn.addEventListener('click', (e) => {
      globalThis.dispatchEvent(new CustomEvent('nested-group-button-click', {
        detail: {
          groupId: group.id,
          levelOne: levelOne.value,
          levelTwo: levelTwo.value,
          isCustomer: isCustemer,
          min: minDisplay,
          max: maxDisplay
        }
      }));
      e.stopPropagation();
    });
    return actionBtn;
  }

  // Main DOM creation
  const groupsContainer = document.createElement("div");
  groupsContainer.classList.add('group-container');
  groupsContainer.dataset.groupId = String(group.id || '');
  groupsContainer.dataset.wcDesc = String(group.wcDesc || group.nestedInGroup || group.id || '');

  const groupTitleContainer = document.createElement("div");
  groupTitleContainer.classList.add('group-title-container');
  groupTitleContainer.style.cursor = 'pointer';

  let nestedInGroupClass = group.nestedInGroup || "undefined-group";
  nestedInGroupClass = nestedInGroupClass.replace(/\s+/g, '-');
  const groupWithId = document.createElement("div");
  groupWithId.classList.add(nestedInGroupClass);

  createGroupTitle(group, groupTitleContainer);

  const groupDescription = document.createElement("div");
  if (shouldUseCreateGroupElement) groupDescription.classList.add('groups-description');

  const nestedGroupsContainer = document.createElement("div");
  nestedGroupsContainer.classList.add('nested-groups');
  if (isShopOrderDoubleGrouping) nestedGroupsContainer.classList.add('shoporder-double');

  if (group.content === group.id || levelOne.value === levelTwo.value) {
    nestedGroupsContainer.innerHTML = "";
  } else {
    nestedGroupsContainer.innerHTML = getCustemerContent(group, isCustemer);
  }

  // Display times
  const { total: totalDisplay, min: minDisplay, max: maxDisplay } = getDisplayTimes(String(group.id));
  if (minDisplay === undefined) {
    delete groupsContainer.dataset.minLaunchWait;
  } else {
    groupsContainer.dataset.minLaunchWait = String(minDisplay);
  }
  if (maxDisplay === undefined) {
    delete groupsContainer.dataset.maxLaunchWait;
  } else {
    groupsContainer.dataset.maxLaunchWait = String(maxDisplay);
  }

