function extractWorkCenters(input: string): string {
  const result: string[] = [];
  const parts = input.split(',');

  for (const part of parts) {
       if (part.includes('parent')) {
      continue; // Skip anything with 'parent'
    }
    const childMatch = part.match(/^child\d+-child\d+-(.+)$/);
    if (childMatch) {
      result.push(childMatch[1]); // Extract value after 'childX-childX-'
    } else {
      result.push(part); // Keep original if not matching
    }
  }

  return result.join(',');
}

