    // Default option for subCat (Second grouping)
    subCatOption.text = t('SecondGrouping');
    subCatOption.disabled = true; 

    subCat.appendChild(subCatOption);

    // Group and Subgroup Data using `content` for both value and display
    const groupsData = [
        { content: 'shopOrder', label: t('Source') },  
        { content: 'sourceType', label: t('SourceType') },  
