        { content: 'sebango', label: t('Sebango') },  
        { content: 'customer', label: t('Customer') }  
    ];

    // Populate the first dropdown (cat) — clear old options first
    cat.innerHTML = '';
    groupsData.forEach(group => {
      const groupOption = document.createElement('option');
      groupOption.value = group.content;
      groupOption.text = group.label || group.content;
      cat.appendChild(groupOption);
    });

    // Update second dropdown (subCat) based on exclusions
    function updateSubCatOptions(selectedValue: string) {
        subCat.innerHTML = ''; // Clear subCat

        // Map exclusions by content instead of id
        const exclusions: { [key: string]: string[] } = {
            'shopOrder': ['shopOrder', 'sourceType'], // Exclude Source and Source Type
            'sourceType': ['shopOrder', 'sourceType'], // Exclude Source and Source Type
            'truck': ['truck', 'destinationType'], // Exclude Truck and Destination Type
            'tpaNumber': ['tpaNumber', 'destinationType'], // Exclude TPA Name and Destination Type
            'destinationType': ['destinationType'], // Exclude Destination Type and TPA Name
            'sebango': ['sebango', 'PDP Family'], // Exclude Sebango and PDP Family
            'PDP Family': ['PDP Family'], // Exclude PDP Family
            'customer': ['customer', 'destinationType'], // Exclude Customer and Destination Type
        };

        const excludedValues = exclusions[selectedValue] || [];

        // Populate the second dropdown (subCat)
        subGroupsData.forEach(group => {
            if (!excludedValues.includes(group.content)) {
                const groupOption = document.createElement('option');
                groupOption.value = group.content;
                groupOption.text = group.label || group.content;
                subCat.appendChild(groupOption);
            }
        });

        // Add the "None" option to replace the last empty option
