    const subCatRef = visCat?.querySelector<HTMLSelectElement>('#lvl-subcat-select') ?? subCat;

    catRef.addEventListener('change', async (event) => {
        const selectedValue = (event.target as HTMLSelectElement).value;
        const selectedGroup = groupsData.find(group => group.content === selectedValue);
        isUpdatingTimeline = false;

        if (selectedGroup) {
            levelOne.value = selectedGroup.content; // Store the selected value
            updateSubCatOptions(selectedGroup.content); // Update second dropdown

            levelTwo.value = selectedGroup?.content;

            try {
