                await fetchAndProcessData(data);
            } catch (error) {
                console.error('Error during fetch and process data:', error);
            } finally {
                $q.loading.hide();
            }

            subCatRef.value = 'filterOption';
        }
    });

        subCatRef.addEventListener('change', async (event) => {
