async function fetchAndProcessData(data: any) {
  try {
    if (!data || !data.wkOrderList) {
      processedData.value = null;
      groups.value = new DataSet<any>([]);
      items.value = new DataSet<any>([]);
      if (itemTimeline.value) {
        itemTimeline.value.setItems(items.value);
        itemTimeline.value.setGroups(groups.value);
      }
      return;
    }

    const result = data.wkOrderList;
    processedData.value = result;
    tpaFulfillmentBackgroundKeys.clear();

    groups.value = new DataSet<any>([]);
    items.value = new DataSet<any>([]);
    await processGroupsNewFormat(result);

    if (ishandleWorkOrderFetched.value) {
      updateTimeline();
    }
    if (isClusteringEnabled.value) {
      options.value.timeAxis = {
        scale: 'minute',
        step: aggrTime
      }
    }
    if (isUpdatingTimeline) return;
    updateTimeline();
    if (itemTimeline.value) {
      itemTimeline.value.setOptions(options.value);
      isUpdatingTimeline = true;
      itemTimeline.value.setGroups(groupStore.groups);
    }
  } catch (error) {
    console.error("Error in fetchAndProcessData:", error);
  }
}

