async function processGroupsNewFormat(result: any) {
  for (const wcKey of Object.keys(result)) {
    const wcGroup = result[wcKey];
    // Each wcGroup has: { [wcKey]: [orders], launcherWaitingTime, minLauncherWaitingTime, maxLauncherWaitingTime }
    const nestedGroupsValues: (string | number)[] = [];
    let level1TpaCode: string | undefined = undefined;
    for (const subKey of Object.keys(wcGroup)) {
      if (Array.isArray(wcGroup[subKey])) {
        nestedGroupsValues.push(`${wcKey}_${subKey}`);
         // Extract tpaCode from the first item if available
        const firstItem = wcGroup[subKey][0];
        const tpaCode = firstItem?.tpaCode;
        if ((level1TpaCode === undefined || level1TpaCode === null) && firstItem) {
          level1TpaCode = firstItem.tpaCode;
        }
        addGroupToDataset(wcKey, subKey, wcGroup[subKey][0]?.wcDesc, wcGroup[subKey][0]?.sourceType, wcGroup[subKey][0]?.customerDesc, false, tpaCode);
        // Pass launcherWaitingTime/min/max to each item in this group
        await processItemsNewFormat(wcKey, subKey, wcGroup[subKey], wcGroup.launcherWaitingTime, wcGroup.minLauncherWaitingTime, wcGroup.maxLauncherWaitingTime);
      }
    }
    addMainGroupToDataset(wcKey, nestedGroupsValues, level1TpaCode);
  }
}

