async function processItemsNewFormat(
  level1Key: string,
  level2Key: string,
  itemsArr: any[],
  launcherWaitingTime: LauncherWaitingTime,
  minLauncherWaitingTime: LauncherWaitingTime,
  maxLauncherWaitingTime: LauncherWaitingTime
) {
  for (const [index, value] of itemsArr.entries()) {
    try {
      const { dateItem, tpaStartDate, tpaEndDate, tpaTruckDeparture } = processDates(value);
      // Attach group-level launcherWaitingTime to each item for tooltip
      const hasValue = (v: unknown): boolean => {
        if (v === null || v === undefined) return false;
        if (typeof v === 'string') return v.trim() !== '';
        return true;
      };
      if (hasValue(launcherWaitingTime)) value.launcherWaitingTime = launcherWaitingTime;
      if (hasValue(minLauncherWaitingTime)) value.minLauncherWaitingTime = minLauncherWaitingTime;
      if (hasValue(maxLauncherWaitingTime)) value.maxLauncherWaitingTime = maxLauncherWaitingTime;
      if (value.newPromiseTime) {
        let newPromisedateItem = new Date(value.newPromiseTime);
        if (filterStore.preReschedule) {
          await addMainItem(level1Key, level2Key, index, value, dateItem, tpaStartDate, tpaEndDate, tpaTruckDeparture, levelOne.value, levelTwo.value, true);
        } else {
          await addMainItem(level1Key, level2Key, index, value, newPromisedateItem, tpaStartDate, tpaEndDate, tpaTruckDeparture, levelOne.value, levelTwo.value);
        }
      } else {
        await addMainItem(level1Key, level2Key, index, value, dateItem, tpaStartDate, tpaEndDate, tpaTruckDeparture, levelOne.value, levelTwo.value);
      }
    } catch (error) {
      console.error("Error processing item (new format):", error);
    }
  }
}

