function determineColorBasedOnRules(alertCreationTime: string, newPromiseTime: string, alertCreated: boolean, now: number): string {
  // Rule 1: Black bell
  if (
    alertCreated &&
    (newPromiseTime === null || newPromiseTime === undefined) && // Checks for both null and undefined
    alertCreationTime &&
    DateTime.fromISO(alertCreationTime, {
      zone: plantTimezone,
    }).toMillis() +
      (toleranceWk.value  ?? 0) * 60000 >
      now
  ) {
    return 'BLACK';
  }
  // Rule 2: Red bell
  if (
    alertCreated &&
    (newPromiseTime === null || newPromiseTime === undefined) && // Checks for both null and undefined
    alertCreationTime &&
    DateTime.fromISO(alertCreationTime.slice(0, 16), {
      zone: plantTimezone,
    }).toMillis() +
      (toleranceWk.value  ?? 0) * 60_000 
      <
        now
  ) {
    return 'RED';
  }

  if (alertCreated && newPromiseTime !== null) {
    return 'BLACK';
  }

  return 'WHITE'; 
}

