function setupScrollTracking(scrollableElement: HTMLElement) {
  let scrollTimeout: number | null = null;

  const markUserScroll = () => {
    isUserInitiatedScroll.value = true;
    lastUserScrollTime.value = Date.now();

    if (scrollTimeout !== null) {
      clearTimeout(scrollTimeout);
    }

    // After 300ms of no scroll, we assume user stopped
    scrollTimeout = window.setTimeout(() => {
      isUserInitiatedScroll.value = false;
      scrollTimeout = null;
    }, 300);
  };

  scrollableElement.addEventListener('wheel', markUserScroll);
  scrollableElement.addEventListener('touchstart', markUserScroll);
  scrollableElement.addEventListener('pointerdown', markUserScroll);

