const updateTimelineWithGroups = () => {
  if (!itemTimeline.value?.groupsData) {
    return;
  }

  const currentGroups = itemTimeline.value.groupsData.get();  


  if (groupStore.lastSavedGroups && groupStore.lastSavedGroups.length > 0) {
    const filteredAndOrderedGroups = groupStore.lastSavedGroups
      .filter(savedGroup =>
        currentGroups.some((group: { id: string }) => group.id === savedGroup.id)
      )
      .map(savedGroup =>
        currentGroups.find((group: { id: string }) => group.id === savedGroup.id)
      );

    const unmatchedGroups = currentGroups.filter((currentGroup: { id: string; }) =>
      !filteredAndOrderedGroups.some((group: { id: string }) => group.id === currentGroup.id)
    );

    const allGroups = [...filteredAndOrderedGroups, ...unmatchedGroups];

    groupStore.setGroups(allGroups);
    itemTimeline.value.setGroups(allGroups);
    itemTimeline.value.redraw();
  } else {
    groupStore.setGroups(currentGroups);
    itemTimeline.value.setGroups(currentGroups);
    itemTimeline.value.redraw();
  }
  // Re-apply after groups change
  applyBlueNestedGroupLabels();
};

