function processSingleSegment(
  segRule: SegmentRule,
  resolved: unknown,
  baseRecord: Record<string, unknown>,
  context: Record<string, unknown>,
): Record<string, unknown> {
  const updated = { ...baseRecord };
  const segResult = processSingleObjectSegment(segRule, resolved, context);
  Object.assign(updated, segResult);

  if (
    segRule.subSegments &&
    segRule.subSegments.length > 0 &&
    typeof resolved === 'object' &&
    resolved !== null
  ) {
    const extractedFields = applyFields(
      segRule.fields,
      resolved as Record<string, unknown>,
      context,
    );
    const subContext = {
      ...context,
      ...updated,
      ...resolved,
      ...extractedFields,
    };
    flattenTargetGroupFields(extractedFields, subContext);

    for (const subRule of segRule.subSegments) {
      if (subRule.array === 'all' && subRule.arrayFieldName) {
        processSingleArrayAllSubSegment(subRule, resolved, subContext, updated);
      } else if (
        (subRule.array === 'first' ||
          subRule.array === 'firstWithProp' ||
          subRule.array === 'firstMatchingBy') &&
        subRule.fields.length > 0
      ) {
        processSingleArrayFirstSubSegment(
          subRule,
          resolved,
          subContext,
          updated,
        );
      } else if (!subRule.array && subRule.fields.length > 0) {
        processSingleNestedObjectSubSegment(
          subRule,
          resolved,
          subContext,
          baseRecord,
          updated,
        );
      }
    }
  }

  return updated;
}

