  value: string,
  update: (callback: () => void) => void,
): Promise<void> {
  if (isReadOnly.value) {
    update(() => {
      suggestionOptions.value = [];
    });
    return;
  }

  const normalizedValue = value.trim();

  if (normalizedValue.length < 3) {
    update(() => {
      suggestionOptions.value = [];
    });
    return;
  }

  isLoadingSuggestions.value = true;

  try {
    const suggestions = await getMaterialSuggestions(
      undefined,
      normalizedValue,
    );
    const assignedIds = new Set(props.rows.map((row) => row.id));

    update(() => {
      suggestionOptions.value = suggestions
        .filter(
          (suggestion): suggestion is MaterialSuggestionDto & { id: number } =>
            suggestion.id !== undefined && !assignedIds.has(suggestion.id),
        )
        .map((suggestion) => ({
          description: suggestion.description ?? undefined,
          id: suggestion.id,
          label:
            suggestion.description && suggestion.description.trim() !== ''
              ? `${suggestion.code} - ${suggestion.description}`
              : suggestion.code,
          value: suggestion.id,
        }));
    });
  } catch {
    update(() => {
      suggestionOptions.value = [];
    });
  } finally {
    isLoadingSuggestions.value = false;
  }
}

