export function checkPlantConsistency(
  logger: AppLogger,
  record: CombinedDtoWithIndex,
  plantCacheService: PlantCacheService,
): boolean {
  try {
    const context = {
      method: 'checkPlantConsistency',
      service: 'checkPlantConsistency',
    };

    // Extract plant ID from either SITE or S_SITE
    const plantId = record.SITE || record.S_SITE;

    if (!plantId) {
      logger.verbose(
        'No plant ID found in record (neither SITE nor S_SITE)',
        context,
      );
      return false;
    }

    const plantCheck = plantCacheService.isPlantValid(Number(plantId));
    if (!plantCheck) {
      logger.verbose(
        `Plant ${plantId} is not defined in the plant list`,
        context,
      );
    }
    return plantCheck;
  } catch (error) {
    logger.error(
      `Error processing message: ${error}`,
      error instanceof Error ? error.stack : error,
    );
    return false;
  }
}

