export async function appendAndSaveToCacheQueue(
  logger: AppLogger,
  queueName: string,
  message: QueueMessage,
  redisClient: RedisClientInstance,
  serviceMutexes: MutexManagerService,
): Promise<void> {
  const context: JobsLogContext = {
    method: 'appendAndSaveToCacheQueue',
    object: queueName,
    plant: message.plant,
    service: 'appendAndSaveToCacheQueue',
  };

  const logOperationInfo = {
    name: 'appendAndSaveToCacheQueue',
    srcLocation: 'append-and-save-to-cache-queue.ts',
  };

  const logOperationDetail = {
    message,
    plantId: message.plant,
    queueName,
  };

  // Ensure message has a plantId
  if (!message.plant) {
    return;
  }

  if (!redisClient) {
    if (message.plant === 1059) {
      logger.log(
        `[DEBUG-1059] appendAndSaveToCacheQueue - Redis client unavailable - queue: ${queueName}`,
        context,
      );
    }
    return;
  }

  // Acquire lock for the queue
  logOperationInfo.name = 'Acquire lock';
  const release = await execAndLog(
    logger,
    () =>
      acquireLockWithTimeout(
        logger,
        `${queueName}-${message.plant}`,
        serviceMutexes,
      ),
    logOperationInfo,
    logOperationDetail,
  );

  if (!release) {
    if (message.plant === 1059) {
      logger.log(
        `[DEBUG-1059] appendAndSaveToCacheQueue - lock not acquired - queue: ${queueName}`,
        context,
      );
    }
    return;
  }

  try {
    const containerPrefix = process.env.STATE_PREFIX ?? 'picking-state-mv';
    const redisQueueKey = `${containerPrefix}:${queueName}:${message.plant}`;

    if (message.plant === 1059) {
      logger.log(
        `[DEBUG-1059] appendAndSaveToCacheQueue - before LRANGE - key: ${redisQueueKey}, isOpen: ${redisClient.isOpen}, isReady: ${redisClient.isReady}`,
        context,
      );
    }

    const existingMessages = await redisClient.lRange(redisQueueKey, 0, -1);
    const messageExists = existingMessages.includes(JSON.stringify(message));

    if (message.plant === 1059) {
      logger.log(
        `[DEBUG-1059] appendAndSaveToCacheQueue - LRANGE result - key: ${redisQueueKey}, count: ${existingMessages.length}, exists: ${messageExists} , message :${message}`,
        context,
      );
    }

    if (messageExists) {
      if (message.plant === 1059) {
        logger.log(
          `[DEBUG-1059] appendAndSaveToCacheQueue - skip LPUSH (duplicate) - key: ${redisQueueKey}`,
          context,
        );
      }
      return;
    }

    await redisClient.lPush(redisQueueKey, JSON.stringify(message));

    if (message.plant === 1059) {
      logger.log(
        `[DEBUG-1059] appendAndSaveToCacheQueue - LPUSH success - key: ${redisQueueKey}`,
        context,
      );
    }
  } catch (error) {
    logger.error(
      `Error appending and saving to cache queue: ${error.message}`,
      context,
      error.stack,
    );
  } finally {
    if (release) release();
  }
}

