async function updatePickingOrdersContainer(
  logger: AppLogger,
  queueMessages: Array<QueueMessage>,
  productionApi: ProductionApi,
  updateCache: UpdateCacheSequentially,
): Promise<void> {
  const pickingOrderIdsByPlant: { [plant: number]: Array<string> } = {};

  for (const queueMessage of queueMessages) {
    const { plant, pickingOrderIdFromContainer } = queueMessage;

    if (pickingOrderIdFromContainer) {
      if (!(plant in pickingOrderIdsByPlant)) {
        pickingOrderIdsByPlant[plant] = [];
      }

      const pickingOrderIds = pickingOrderIdFromContainer
        .split(';')
        .map((id) => id.trim())
        .filter(Boolean);

      pickingOrderIdsByPlant[plant].push(...pickingOrderIds);
    }
  }

  // Process all plants concurrently
  const plantPromises = Object.keys(pickingOrderIdsByPlant).map(
    async (plantKey) => {
      const plant = Number(plantKey);
      const containerDetails =
        await productionApi.fetchContainerByPlantAndPickingOrderIdList(
          plantKey,
          pickingOrderIdsByPlant[plant],
        );
      const updatedData = Object.fromEntries(
        Object.entries(containerDetails).map(([key, value]) => [
          key,
          {
            updates: {
              realProductionTime: value.bookDate,
              createOn: value.createOn,
              huCurrentStorageLocation: value.currentStorageLocation,
            },
          },
        ]),
      );
      if (updatedData) {
        await updateCache.replaceUpdateTocosmos(updatedData, plant);
      }
    },
  );

  await Promise.all(plantPromises);
}

