async function updatePickingOrdersTransfer(
  queueMessages: Array<QueueMessage>,
  orderApi: OrderApi,
  transferApi: TransferApi,
  updateCache: UpdateCacheSequentially,
): Promise<void> {
  const containerIdsByPlant: { [plant: number]: Array<string> } = {};

  for (const queueMessage of queueMessages) {
    if (queueMessage.containerId) {
      const { plant } = queueMessage;
      if (!containerIdsByPlant[plant]) {
        containerIdsByPlant[plant] = [];
      }
      containerIdsByPlant[plant].push(queueMessage.containerId);
    }
  }

  const plants = Object.keys(containerIdsByPlant);
  await pMap(
    plants,
    async (plantLinked) => {
      const plant = Number(plantLinked);
      const pickingOrderIdsDto = new PickingByContainerIdRequestDto();
      pickingOrderIdsDto.containerIds = containerIdsByPlant[plant];
      pickingOrderIdsDto.plant = plant;

      const plantPickingOrders =
        await orderApi.fetcheOrdersByrelatedLabel(pickingOrderIdsDto);
      const transferData =
        await transferApi.fetchTransferDetailsByContainers(pickingOrderIdsDto);

      if (!plantPickingOrders || !transferData) return;

      const transferMap = new Map(Object.entries(transferData));

      const updatedOrders: Record<string, OrderUpdate> = {};

      for (const order of plantPickingOrders) {
        const match = transferMap.get(order.relatedLabel);
        if (match) {
          updatedOrders[order.pickingOrderId] = {
            updates: {
              dateTransfer: match.createdOn,
              huCurrentStorageLocation: match.destinationLocation,
            },
          };
        }
      }

      await updateCache.replaceUpdateTocosmos(updatedOrders, plant);
    },
    { concurrency: 2 }, // Adjust as needed
  );
}

