export async function processQueueMessages(
  logger: AppLogger,
  queueMessages: Array<QueueMessage>,
  queueMessagesTpa: Array<QueueMessage>,
  queueMessagesWkFromContainer: Array<QueueMessage>,
  queueMessagesWkFromTransfer: Array<QueueMessage>,
  orderApi: OrderApi,
  shipmentApi: ShipmentApi,
  productionApi: ProductionApi,
  transferApi: TransferApi,
  updateCache: UpdateCacheSequentially,
): Promise<void> {
  if (queueMessages.length > 0) {
    const { plant } = queueMessages[0];
    const outboundsList: Array<string> = queueMessages.map(
      (queueMessage) => queueMessage.outbound ?? '',
    );
    await updatesWKLinkedToOutbound(
      plant,
      outboundsList,
      orderApi,
      shipmentApi,
      updateCache,
    );
  }
  if (queueMessagesTpa.length > 0) {
    const assignIds: Array<number> = queueMessagesTpa
      .map((q) =>
        q.tpaAssignement === undefined ? undefined : Number(q.tpaAssignement),
      )
      .filter((n): n is number => n !== undefined);

    const outboundList =
      await shipmentApi.getoutboundByPlantAndTpaAssignmentList(
        Number(queueMessagesTpa[0].plant),
        assignIds,
      );
    if (outboundList && outboundList.length > 0) {
      await updatesWKLinkedToOutbound(
        Number(queueMessagesTpa[0].plant),
        outboundList,
        orderApi,
        shipmentApi,
        updateCache,
      );
    }
  }

  if (queueMessagesWkFromContainer.length > 0) {
    await updatePickingOrdersContainer(
      logger,
      queueMessagesWkFromContainer,
      productionApi,
      updateCache,
    );
  }

  if (queueMessagesWkFromTransfer.length > 0) {
    await updatePickingOrdersTransfer(
      queueMessagesWkFromTransfer,
      orderApi,
      transferApi,
      updateCache,
    );
  }
}

