async function loadGroups() {
  try {
    const plant = String(criteriaId);
    const appName = isAlertScreen.value ? 'ALERT-SCREEN' : 'PICKING-SCREEN';

    const rawConfigs = await filterStore.fetchFilterConfigByPlant(
      plant,
      appName,
    );

    const mappedConfigs: Array<GroupDisplay> = rawConfigs.map(
      (config: any, index: number) => {
        const userCriteriaString = config.userCriteria || '';
        const criteriaKeys = userCriteriaString
          .split(';')
          .map((pair: string) => pair.split(':')[0].trim())
          .filter(Boolean);

        return {
          id: config.id ?? index + 1,
          name: config.groupName,
          userCriteria: userCriteriaString,
          selectedFilter: criteriaKeys.join(', '),
          createdAt: config.createdAt,
        };
      },
    );

    groups.value = mappedConfigs.sort(
      (a, b) =>
        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
    );
  } catch (error) {
    console.error('Failed to fetch filter configs:', error);
  }
}

