  clonedSourceProperties: Array<PhysicalAssetClassProperty>,
  physicalAssetClassId: number,
  resolvedPropertiesBySourceId: Map<number, PhysicalAssetClassProperty>,
  parentPropertiesById: Map<number, PhysicalAssetClassProperty>,
  currentPropertiesByCode: Map<string, PhysicalAssetClassProperty>,
): Array<PhysicalAssetClassProperty> {
  return clonedSourceProperties.flatMap((sourceProperty) => {
    const clonedProperty = resolvedPropertiesBySourceId.get(sourceProperty.id);
    if (!clonedProperty) return [];

    const resolvedParentId = resolveParentPropertyId(
      sourceProperty,
      physicalAssetClassId,
      resolvedPropertiesBySourceId,
      parentPropertiesById,
      currentPropertiesByCode,
    );

    if (
      clonedProperty.parentPhysicalAssetClassPropertyId === resolvedParentId
    ) {
      return [];
    }

    clonedProperty.parentPhysicalAssetClassPropertyId = resolvedParentId;
    return [clonedProperty];
  });
}

