async function clonePropertyForClass(
  manager: EntityManager,
  physicalAssetClassId: number,
  sourceProperty: PhysicalAssetClassProperty,
): Promise<PhysicalAssetClassProperty> {
  const propertyRepository = manager.getRepository(PhysicalAssetClassProperty);
  const descriptionRepository = manager.getRepository(
    PhysicalAssetClassPropertyDescription,
  );

  const clonedProperty = propertyRepository.create({
    code: sourceProperty.code,
    isCustom: sourceProperty.isCustom,
    length: sourceProperty.length,
    parentPhysicalAssetClassPropertyId:
      sourceProperty.parentPhysicalAssetClassPropertyId,
    physicalAssetClassId,
    propertyDataTypeId: sourceProperty.propertyDataTypeId,
    propertySemanticsJson: sourceProperty.propertySemanticsJson,
    scale: sourceProperty.scale,
  });
  const savedClonedProperty = await propertyRepository.save(clonedProperty);

  const descriptions = await descriptionRepository.find({
    where: { physicalAssetClassPropertyId: sourceProperty.id },
  });

  if (descriptions.length > 0) {
    await descriptionRepository.save(
      descriptions.map((description) =>
        descriptionRepository.create({
          code: description.code,
          description: description.description,
          physicalAssetClassPropertyId: savedClonedProperty.id,
        }),
      ),
    );
  }

  return savedClonedProperty;
}

