export async function replacePhysicalAssetClassPropertiesByCloning(
  manager: EntityManager,
  physicalAssetClassId: number,
  nextPropertyIds: Array<number>,
): Promise<void> {
  const normalizedPropertyIds = normalizePropertyIds(nextPropertyIds);
  const propertyRepository = manager.getRepository(PhysicalAssetClassProperty);
  const descriptionRepository = manager.getRepository(
    PhysicalAssetClassPropertyDescription,
  );
  const currentClassProperties = await propertyRepository.find({
    where: { physicalAssetClassId },
    relations: ['descriptions'],
    order: { id: 'ASC' },
  });
  const currentPropertiesByCode = new Map(
    currentClassProperties.map((property) => [property.code, property]),
  );

  if (normalizedPropertyIds.length === 0) {
    const currentPropertyIds = currentClassProperties.map(
      (property) => property.id,
    );

    await deletePhysicalAssetClassPropertiesById(
      propertyRepository,
      descriptionRepository,
      currentPropertyIds,
    );
    return;
  }

  const sourceProperties = await propertyRepository.find({
    where: { id: In(normalizedPropertyIds) },
    relations: ['descriptions'],
    order: { id: 'ASC' },
  });
  const sourcePropertiesById = new Map(
    sourceProperties.map((property) => [property.id, property]),
  );
  assertPropertiesExist(normalizedPropertyIds, sourcePropertiesById);
  const orderedSourceProperties = normalizedPropertyIds.map(
    (propertyId) =>
      sourcePropertiesById.get(propertyId) as PhysicalAssetClassProperty,
  );
  const { aliasedCloneSourceIds, cloneRequests, resolvedPropertiesBySourceId } =
    planPropertyReplacement(
      orderedSourceProperties,
      currentPropertiesByCode,
      physicalAssetClassId,
    );
  const clonedProperties = await Promise.all(
    cloneRequests.map(async (sourceProperty) => ({
      clonedProperty: await clonePropertyForClass(
        manager,
        physicalAssetClassId,
        sourceProperty,
      ),
      sourcePropertyId: sourceProperty.id,
    })),
  );

  for (const { clonedProperty, sourcePropertyId } of clonedProperties) {
    currentPropertiesByCode.set(clonedProperty.code, clonedProperty);
    resolvedPropertiesBySourceId.set(sourcePropertyId, clonedProperty);
  }

  for (const [
    sourcePropertyId,
    aliasedSourcePropertyId,
  ] of aliasedCloneSourceIds) {
    const aliasedClonedProperty = resolvedPropertiesBySourceId.get(
      aliasedSourcePropertyId,
    );

    if (aliasedClonedProperty) {
      resolvedPropertiesBySourceId.set(sourcePropertyId, aliasedClonedProperty);
    }
  }

  const parentIdsToLoad = getParentIdsToLoad(orderedSourceProperties);
  const parentProperties =
    parentIdsToLoad.length === 0
      ? []
      : await propertyRepository.find({
          where: { id: In(parentIdsToLoad) },
          select: [
            'id',
            'code',
            'physicalAssetClassId',
            'parentPhysicalAssetClassPropertyId',
          ],
        });
  const parentPropertiesById = new Map(
    parentProperties.map((property) => [property.id, property]),
  );
  const propertiesNeedingParentUpdate = buildPropertiesNeedingParentUpdate(
    cloneRequests,
    physicalAssetClassId,
    resolvedPropertiesBySourceId,
    parentPropertiesById,
    currentPropertiesByCode,
  );

  if (propertiesNeedingParentUpdate.length > 0) {
    await propertyRepository.save(propertiesNeedingParentUpdate);
  }

  const desiredPropertyIds = new Set(
    [...resolvedPropertiesBySourceId.values()].map((property) => property.id),
  );
  const propertyIdsToDelete = currentClassProperties
    .map((property) => property.id)
    .filter((propertyId) => !desiredPropertyIds.has(propertyId));

  await deletePhysicalAssetClassPropertiesById(
    propertyRepository,
    descriptionRepository,
    propertyIdsToDelete,
  );
}

