/**
 * Adds visible/all property projections to physical asset properties.
 * @param physicalAssets Physical assets whose properties are enriched.
 */
export function enrichPhysicalAssetProperties(
  physicalAssets: Array<PhysicalAsset>,
): void {
  for (const physicalAsset of physicalAssets) {
    for (const property of physicalAsset.physicalAssetProperties ?? []) {
      const propertiesJson = property.propertiesJson ?? {};
      const codeIndex = createPropertyCodeIndex(
        property.physicalAssetClass?.physicalAssetClassProperties ?? [],
      );

      const allProperties = Object.entries(propertiesJson).map(
        ([jsonKey, value]) => {
          const classProperty = codeIndex.get(
            normalizePhysicalAssetPropertyKey(jsonKey),
          );

          return {
            ...(classProperty ?? {
              code: jsonKey,
              propertySemanticsJson: nullableValue,
            }),
            jsonKey,
            propertySemanticsJson: classProperty
              ? PhysicalAssetClassPropertySemanticsTransformerDto.toApi(
                  classProperty.propertySemanticsJson,
                )
              : nullableValue,
            value,
          };
        },
      );

      const visibleProperties = allProperties.filter((entry) => {
        const semantics = entry.propertySemanticsJson;
        if (!semantics || typeof semantics !== 'object') return true;

        return (semantics as Record<string, unknown>).visible !== false;
      });

      Object.assign(property, {
        allProperties,
        visibleProperties,
      });

      if (property.physicalAssetClass) {
        property.physicalAssetClass.physicalAssetClassProperties = [];
      }
    }
  }
}

