  if (!classProperties || Object.keys(properties).length === 0) {
    return properties;
  }

  const propertyIndex = createPropertyCodeIndex(classProperties);
  const normalizedProperties = { ...properties };

  for (const [jsonKey, value] of Object.entries(properties)) {
    const classProperty = propertyIndex.get(
      normalizePhysicalAssetPropertyKey(jsonKey),
