      const cardinality =
        apiSemantics.cardinality === 'array' ? 'array' : 'single';
      const allowedValues = Array.isArray(apiSemantics.allowedValues)
        ? apiSemantics.allowedValues.map(String)
        : undefined;
      const dataTypeKind = getPropertyDataTypeKind(
        classProperty.propertyDataTypeId,
        classProperty.propertyDataType?.code,
