/**
 * Applies class-scoped property payloads in a deterministic write order.
 * @param equipment Equipment entity receiving class property values.

code_excerpt:
export async function applyClassProperties(
  equipment: Equipment,
  classProperties: Array<EquipmentClassPropertiesInputDto>,
  logger: EquipmentCrudLogger,
  equipmentPropertyRepository: Repository<EquipmentProperty>,
  equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
): Promise<WrappedResponse<null | undefined> | undefined> {
  // Keep writes ordered to reduce lock contention and duplicate-create races.
  const applyAtIndex = async (
    index: number,
  ): Promise<WrappedResponse<null | undefined> | undefined> => {
    if (index >= classProperties.length) {
      return undefined;
    }

    const entry = classProperties[index];
    const propertyId = await resolveOrCreateEquipmentPropertyId(
      equipment,
      logger,
      equipmentPropertyRepository,
      equipmentEquipmentClassRepository,
      entry.equipmentClassId,
    );

    if (propertyId !== undefined) {
      const mergeError = await mergeJsonPropertiesByPropertyId(
        propertyId,
        entry.properties,
        equipmentPropertyRepository,
      );

      if (mergeError) {
        return mergeError;
      }
    }

    return applyAtIndex(index + 1);
  };

  return applyAtIndex(0);
}

