      );
      const updated = await updatePhysicalAssetClass(classId, {
        code,
        description,
        descriptionLanguageCode: 'EN',
        parentPhysicalAssetClassId,
      });

      if (!updated) {
        notify?.error({ message: 'Failed to save physical asset class.' });
        return;
      }

      await replacePhysicalAssetClassProperties(classId, {
        propertyIds: sanitizedPropertyAssignmentIds,
      });

      const refreshedClass = await getPhysicalAssetClassWithRelations(
        classId,
      ).catch(() => undefined);

      upsertClassRow(
        refreshedClass ?? {
          ...updated,
          description: updated.description ?? description,
        },
      );

      if (selectedClass.value?.id === classId) {
        await refreshSelectedClassState();
      }

      notify?.success({ message: 'Physical asset class updated.' });
      classDialogOpen.value = false;
      return;
    }

    const sanitizedPropertyAssignmentIds = sanitizePropertyAssignmentIds(
      payload.propertyAssignmentIds,
    );
    const created = await createPhysicalAssetClass({
