      descriptionLanguageCode: 'EN',
      parentPhysicalAssetClassId,
    });

    if (!created) {
      notify?.error({ message: 'Failed to create physical asset class.' });
      return;
    }

    if (sanitizedPropertyAssignmentIds.length > 0) {
      await replacePhysicalAssetClassProperties(created.id, {
        propertyIds: sanitizedPropertyAssignmentIds,
      });
    }

    const createdWithRelations = await getPhysicalAssetClassWithRelations(
      created.id,
    ).catch(() => undefined);

    const createdRow: Isa95PhysicalAssetClassDto = {
      ...(createdWithRelations ?? created),
      code: createdWithRelations?.code ?? created.code ?? code,
      description:
        createdWithRelations?.description
