async function confirmDeleteClass(): Promise<void> {
  const classId = pendingDeleteClassId.value;
  if (classId === undefined) {
    cancelDeleteClass();
    return;
  }

  cancelDeleteClass();

  try {
    await deletePhysicalAssetClass(classId);
    physicalAssetClassRows.value = physicalAssetClassRows.value.filter(
      (row) => row.id !== classId,
