    );

    if (selectedClass.value?.id === classId) {
      closePropertiesView();
      selectedClass.value = undefined;
      classProperties.value = [];
    }

    notify?.success({ message: 'Physical asset class deleted.' });
  } catch (error) {
    console.error('Delete physical asset class failed', error);

    let message = 'Failed to delete physical asset class.';

    if (axios.isAxiosError(error)) {
      const resp = error.response as any | undefined;
      if (resp) {
        const status = resp.status;
        if (status === 401) {
          message = 'Unauthorized — please sign in and try again.';
        } else if (status === 403) {
          message = 'Forbidden — you do not have permission to delete this class.';
        } else if (status === 404) {
          message = 'Physical asset class not found.';
        } else if (resp.data && (resp.data.message || resp.data.error)) {
          message = String(resp.data.message || resp.data.error);
        } else if (error.message) {
          message = error.message;
        }
      } else if (error.message) {
        message = `Network error: ${error.message}`;
      }
    } else if (error instanceof Error) {
      message = error.message;
    }

    notify?.error({ message });
  }
}

