function validatePanelCustomPropertyCodes(
  classId: number,
  submission: PhysicalAssetAssignmentsSubmitPayload,
): void {
  const updatedPropertyIds = new Set(
    submission.updatedCustomProperties.map((property) => property.id),
  );
  const seenCodes = new Set(
    getCurrentClassProperties(classId)
      .filter((property) => !updatedPropertyIds.has(property.id))
      .map((property) => getComparablePropertyCode(property.code))
      .filter((code) => code.length > 0),
  );

  const nextProperties = [
    ...submission.updatedCustomProperties.map((property) => property.form),
    ...submission.createdCustomProperties,
  ];

  for (const property of nextProperties) {
    const currentCode = getComparablePropertyCode(property.code);
    if (currentCode.length === 0) {
      throw new Error('Property name is required.');
    }

    if (seenCodes.has(currentCode)) {
      throw new Error(
        `Property name "${property.code.trim()}" already exists.`,
      );
    }

    seenCodes.add(currentCode);
  }
}

