  ticket: DownTimeTicket,
  shiftStart: Date,
  shiftEnd: Date,
  firstShiftHour: string,
): string | undefined {
  const startedInShift =
    ticket.startDate >= shiftStart && ticket.startDate < shiftEnd;

  if (startedInShift) {
    return ticket.startDate.getUTCHours().toString().padStart(2, '0');
  }

  const remainsActiveIntoShift =
    ticket.startDate < shiftStart && ticket.endDate === null;

  if (remainsActiveIntoShift) {
    return firstShiftHour;
  }

  return undefined;
}

