function isDowntimeJustificationRequired(ticket: DownTimeTicket): boolean {
  const isCause1Missing =
    ticket.cause1 === null ||
    ticket.cause1 === undefined ||
    ticket.cause1 === '';
  const remark = ticket.remark?.trim() ?? '';
  const hasEmptyRemark = remark === '';

  if (!isCause1Missing || !hasEmptyRemark) {
    return false;
  }

  if (ticket.cause === 5) {
    return !ticket.nonQualityFlag;
  }

  return ticket.cause === 1 || ticket.cause === 4;
}

