 * @param ticket The downtime ticket to evaluate.

code_excerpt:
function isJitReclassificationRequired(
  ticket: DownTimeTicket,
  shiftStart: Date,
  shiftEnd: Date,
  threshold?: number,
): boolean {
  if (threshold === undefined) {
    return false;
  }

  const isMachineTicket =
    ticket.userId === 'TAG' || ticket.userId === 'API_NTRS';

  if (!isMachineTicket) {
    return false;
  }

  const isUnmodifiedByUser =
    ticket.modifiedBy === null ||
    ticket.modifiedBy === undefined ||
    ticket.modifiedBy.trim() === '';

  if (!isUnmodifiedByUser) {
    return false;
  }

  const durationSeconds =
    typeof ticket.duration === 'number'
      ? ticket.duration
      : Math.floor((Date.now() - ticket.startDate.getTime()) / 1000);

  if (durationSeconds <= threshold) {
    return false;
  }

  const startedInShift = ticket.startDate >= shiftStart;
  const endedInShift =
    ticket.endDate !== null &&
    ticket.endDate !== undefined &&
    ticket.endDate >= shiftStart &&
    ticket.endDate < shiftEnd;

  return startedInShift || endedInShift || ticket.endDate === null;
}

