/**
 * Resolves every notification category that applies to a ticket.
 * @param ticket The downtime ticket to evaluate.

code_excerpt:
function resolveNotificationCategories(
  ticket: DownTimeTicket,
  shiftStart: Date,
  shiftEnd: Date,
  threshold?: number,
): Array<ShiftNotificationTicketDto['type']> {
  const categories: Array<ShiftNotificationTicketDto['type']> = [];
  const startedInShift =
    ticket.startDate >= shiftStart && ticket.startDate < shiftEnd;
  const activeFromPreviousShift =
    ticket.startDate < shiftStart && ticket.endDate === null;

  if (ticket.cause === 6 && (startedInShift || activeFromPreviousShift)) {
    categories.push('UNCLASSIFIED');
  }

  if (startedInShift && isDowntimeJustificationRequired(ticket)) {
    categories.push('DOWNTIME_JUSTIFICATION');
  }

  if (isJitReclassificationRequired(ticket, shiftStart, shiftEnd, threshold)) {
    categories.push('JIT_RECLASSIFICATION');
  }

  return categories;
}

