export function formatDurationAsHhMmSs(totalSeconds: number): string {
  const safeSeconds = Math.min(359_999, Math.max(0, Math.floor(totalSeconds)));
  const hours = Math.floor(safeSeconds / 3600)
    .toString()
    .padStart(2, '0');
  const minutes = Math.floor((safeSeconds % 3600) / 60)
    .toString()
    .padStart(2, '0');
  const seconds = (safeSeconds % 60).toString().padStart(2, '0');

  return `${hours}:${minutes}:${seconds}`;
}

