export function extractCommitIdFromUrl(
  url: string,
  logger: AppLogger,
): string | undefined {
  const context: JobsLogContext = {
    method: 'extractCommitIdFromUrl',
    service: 'CommitUrlUtils',
  };

  try {
    const decoded = decodeURIComponent(url);
    const patterns = [
      /\/commit\/(\w{7,40})(?:[/?#]|$)/u,
      /\/commits\/(\w{7,40})(?:[/?#]|$)/u,
      /%2F([a-f0-9]{7,40})$/iu,
      /\/([a-f0-9]{7,40})$/iu,
    ];

    for (const pattern of patterns) {
      const match = pattern.exec(decoded);
      if (match?.[1]) {
        return match[1];
      }
    }

    return undefined;
  } catch (error) {
    logger.warn(
      `[SERVICE] Failed to parse commit URL '${url}': ${error ? String(error) : error}`,
      context,
    );
    return undefined;
  }
}

