function createEventHubConsumerClient(
  config: EventHubSdkConfig,
  checkpointStore: BlobCheckpointStore,
  logger: AppLogger,
): EventHubConsumerClient {
  const context = createLogContext(
    'createEventHubConsumerClient',
    config.eventHubName,
  );
  const retryOptions = {
    retryDelayInMs: 1000,
    maxRetryDelayInMs: 15_000,
  };

  if (shouldUseConnectionString(config)) {
    // DEV/TEST ONLY: connection string auth bypasses managed identity — do not use in production
    logger.warn(
      `[${config.eventHubName}] EventHub connection string is defined - using connection string authentication instead of DefaultAzureCredential. Do not use connection strings in production.`,
      context,
    );
    return new EventHubConsumerClient(
      config.consumerGroup,
      config.eventHubConnectionString as string,
      config.eventHubName,
      checkpointStore,
      { retryOptions },
    );
  }

  const credential = new DefaultAzureCredential();
  const fullyQualifiedNamespace = `${config.eventHubNamespace}.servicebus.windows.net`;

  return new EventHubConsumerClient(
    config.consumerGroup,
    fullyQualifiedNamespace,
    config.eventHubName,
    credential,
    checkpointStore,
    { retryOptions },
  );
}

