  if (value === undefined || value === null) {
    return '';
  }
  if (
    typeof value !== 'string' ||
    value === '' ||
    value === 'System' ||
    value === 'MESXSystem'
  ) {
    return String(value); // Ensure original value is preserved if it's not a valid string to mask
  }
  return '***';
}

