export async function appendAndSaveToCacheQueue(
  context: AppendAndSaveToCacheQueueInterface,
): Promise<void> {
  const {
    customLogger,
    daprClient,
    redisStoreNameAmr,
    services,
    inMemoryQueue,
    processingQueue,
    plantList,
    data,
  } = context;
  const { mappingService, serviceMutexes } = services;
  const { key, record, sourceTable, operation } = data;

  const dateFunctionStart = Date.now();
  const logOperationInfo = {
    name: '',
    srcLocation: 'appendAndSaveToCacheQueue',
  };
  const logOperationDetail = {
    key,
  };
  const contextLog: JobsLogContext = {
    method: 'appendAndSaveToCacheQueue',
    service: 'queues',
  };
  try {
    const destinations = mappingService.getDestinationsForSource(sourceTable);
    const mappedOutputs =
      destinations.length > 1
        ? mappingService.mapAllData(sourceTable, record, plantList)
        : [mappingService.mapData(sourceTable, record, plantList)];

    const newRecords = mappedOutputs
      .filter(({ mappedData }) =>
        checkPlantConsistency(customLogger, mappedData, plantList),
      )
      .map(({ mappedData, destination, ingestionEventTracking }) => ({
        destination,
        ingestionEventTracking,
        mappedData,
        operation,
        sourceTable,
      }));
    if (newRecords.length === 0) return;

    logOperationInfo.name = 'Acquire lock';
    const release = await execAndLog(
      customLogger,
      () =>
        acquireLockWithTimeout(customLogger, contextLog, serviceMutexes, key),
      logOperationInfo,
      logOperationDetail,
    );

    if (!release) {
      customLogger.error(
        `Error: Failed to acquire lock for ${key}, skipping processing.`,
        contextLog,
      );
      await moveToDeadLetterQueue(
        customLogger,
        contextLog,
        redisStoreNameAmr,
        daprClient,
        key,
        record,
        MESSAGE_ACTION.APPEND,
      );
      return;
    }

    try {
      logOperationInfo.name = 'Save record in queue cache';
      await execAndLog(
        customLogger,
        async () => {
          for (const rec of newRecords) {
            inMemoryQueue[rec.destination].push(rec);
          }
        },
        logOperationInfo,
        logOperationDetail,
      );
    } catch (error) {
      customLogger.error(
        `Error appending and saving queue Message: ${error.message}`,
        contextLog,
        error.stack,
      );
      await moveToDeadLetterQueue(
        customLogger,
        contextLog,
        redisStoreNameAmr,
        daprClient,
        key,
        record,
        MESSAGE_ACTION.APPEND,
      );
    } finally {
      if (!processingQueue[key] && inMemoryQueue[key].length > 1) {
        const processingQueueAlias = processingQueue;
        processingQueueAlias[key] = true;
      }

      if (release) {
        if (record) {
          logOperationInfo.name = 'appendAndSaveToCacheQueue function runtime';
          await execAndLog(
            customLogger,
            async () => {},
            logOperationInfo,
            logOperationDetail,
            dateFunctionStart,
          );
        }
        release();
      }
    }
  } catch (error) {
    customLogger.error(
      `Error processing queue:${error.message}`,
      contextLog,
      error.stack,
    );
    await moveToDeadLetterQueue(
      customLogger,
      contextLog,
      redisStoreNameAmr,
      daprClient,
      key,
      record,
      MESSAGE_ACTION.APPEND,
    );
  }
}

