export function checkPlantConsistency(
  logger: AppLogger,
  mappedData: unknown,
  listPlant: Array<PlantsResponseDto>,
): boolean {
  const context = {
    method: 'checkPlantConsistency',
    service: 'checkPlantConsistency',
  };
  try {
    // Safely extract plant (may come from dynamic mapping even if entity type lacks 'plant')
    const plantValue = (mappedData as Record<string, unknown>)?.plant;
    if (plantValue === undefined || plantValue === null) {
      // If plant not present, assume pass (detail row may still include plant via keys, but avoid hard error)
      return true;
    }
    const plantNumeric = Number(plantValue);
    const plantCheck = listPlant.some(
      (plant: PlantsResponseDto) => plant.plantId === plantNumeric,
    );
    if (!plantCheck) {
      const plantDisplay =
        plantValue !== null && typeof plantValue === 'object'
          ? JSON.stringify(plantValue)
          : '';
      // Avoid logging excessively large plant list repeatedly; log only IDs.
      const plantIds = listPlant.map((p) => p.plantId);
      logger.verbose(
        `Plant ${plantDisplay} is not defined in known plant IDs ${JSON.stringify(plantIds)}`,
        context,
      );
    }
    return plantCheck;
  } catch (error) {
    logger.error(`Error processing message: ${error}`, context, error.stack);
  }
  return false; // Return false in case of an error or if no other return statement is reached
}

