 * Builds a MERGE query that inserts roles only when missing.
 * @param roles Role names to ensure in database.

code_excerpt:
export function buildMergeRoleQuery(roles: Array<string>): string {
  if (roles.length === 0) {
    return '';
  }

  const roleValues = roles.map((role) => `('${role}')`).join(',\n');
  return `
    MERGE role AS target
    USING (
      VALUES
        ${roleValues}
    ) AS source(role_name)
    ON target.role_name = source.role_name
    WHEN NOT MATCHED THEN
      INSERT (role_name, created_at, updated_at)
      VALUES (source.role_name, GETDATE(), GETDATE());
  `;
}

